import subprocess
from decimal import Decimal
def run(f):
    p=subprocess.run(["./executable","-n","-c",f],input=b"",capture_output=True)
    print(f,"->",p.stdout.decode().strip(),"pyDec", end=" ")
    try: print(str(Decimal(f)))
    except Exception as e: print(e)
for f in ["1"*100, "1."+"1"*100, "0."+"0"*50+"1"*50, "1234567890"*20, "1e999999999999999999", "1e-999999999", "0."+"1"*500, "1"+"0"*500]:
    run(f)
# Invalid json numbers?
def runin(inp):
    p=subprocess.run(["./executable","-c","."],input=inp.encode(),capture_output=True)
    print(repr(inp),p.returncode,repr(p.stdout),repr(p.stderr))
for inp in ["01\n","1.\n",".5\n","+1\n","-01\n","1e\n","1e+\n","0x1\n","NaN\n","Infinity\n","-Infinity\n","1_000\n","١٢٣\n"]:
    runin(inp)
# filter literals invalid
for f in ["01","1.",".5","+1","0x1","1_000"]:
    p=subprocess.run(["./executable","-n","-c",f],input=b"",capture_output=True)
    print("filter",f,p.returncode,repr(p.stdout),repr(p.stderr))
