import subprocess
def run(f):
    p=subprocess.run(["./executable","-n","-c",f],input=b"",capture_output=True)
    return p.stdout.decode().strip()
for e in range(24,40):
    print(e, run(f"(1.2345678901234567e{e})+0"))
for e in range(14,22):
    print("1234",e, run(f"(1.234e{e})+0")) # L4
for e in range(14,22):
    print("frac",e, run(f"(1.2345678901234567e{e})+0.5")) 
