# ---------------- Values ----------------
class JNum:
    __slots__ = ("f", "lit", "_dec")
    def __init__(self, f, lit=None):
        self.f = float(f)
        self.lit = lit
        self._dec = None
    def __repr__(self):
        return f"JNum({self.f!r},{self.lit!r})"
    @property
    def dec(self):
        if self._dec is None and self.lit is not None:
            try:
