    low = t.lower()
    sign = 1.0
    body = low
    if body[:1] in "+-":
        if body[0] == "-":
            sign = -1.0
        body = body[1:]
    if body in ("inf", "infinity"):
        return JNum(math.inf * sign)
    if body in ("nan",):
        return JNum(math.nan)
    # Validate decimal syntax similar to decNumber: digits with optional dot, or .digits, optional exponent
    if not re.fullmatch(r"(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?", t):
