        return a == b
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(jq_equal(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        if len(a) != len(b):
            return False
        for k, v in a.items():
            if k not in b or not jq_equal(v, b[k]):
                return False
        return True
    return False

_TYPE_ORDER = {"null": 0, "boolean": 1, "number": 2, "string": 3, "array": 4, "object": 5}

def jq_cmp(a, b):
    ta = type_name(a); tb = type_name(b)
    if ta != tb:
        return -1 if _TYPE_ORDER[ta] < _TYPE_ORDER[tb] else 1
    if ta == "null":
        return 0
    if ta == "boolean":
        return -1 if (a is False and b is True) else (1 if (a is True and b is False) else 0)
    if ta == "number":
        if a.lit is not None and b.lit is not None:
            da = a.dec; db = b.dec
            return -1 if da < db else (1 if da > db else 0)
        fa = a.f; fb = b.f
        a_nan = math.isnan(fa); b_nan = math.isnan(fb)
        if a_nan and b_nan:
            return -1
        if a_nan:
            return -1
        if b_nan:
            return 1
        return -1 if fa < fb else (1 if fa > fb else 0)
    if ta == "string":
        return -1 if a < b else (1 if a > b else 0)
    if ta == "array":
        for x, y in zip(a, b):
            c = jq_cmp(x, y)
            if c:
                return c
        return -1 if len(a) < len(b) else (1 if len(a) > len(b) else 0)
    if ta == "object":
        ka = sorted(a.keys()); kb = sorted(b.keys())
        c = jq_cmp(ka, kb)
        if c:
            return c
        for k in ka:
            c = jq_cmp(a[k], b[k])
            if c:
                return c
        return 0
    return 0

def format_plain_double(f):
    if math.isnan(f):
        return "null"
    if math.isinf(f):
        return "-1.7976931348623157e+308" if f < 0 else "1.7976931348623157e+308"
    if f == 0.0:
        return "-0" if math.copysign(1.0, f) < 0 else "0"
    sign = "-" if f < 0 else ""
    af = abs(f)
    s = repr(af)
    # parse repr into digits and decimal point position D (value = 0.digits * 10^D)
    if "e" in s or "E" in s:
        mant, exp = re.split("[eE]", s)
        exp = int(exp)
        digits = mant.replace(".", "")
        D = exp + 1
    elif "." in s:
        ip, fp = s.split(".")
        if ip != "0":
            digits = ip + fp
            D = len(ip)
        else:
            # count leading zeros in fp
            lz = 0
            while lz < len(fp) and fp[lz] == "0":
                lz += 1
            digits = fp[lz:]
            D = -lz
    else:
        digits = s
        D = len(s)
    digits = digits.lstrip("0") or "0"
    # strip trailing zeros (repr for integral floats gives .0)
    while len(digits) > 1 and digits.endswith("0"):
        digits = digits[:-1]
    L = len(digits)
    if D < -3 or (D - L) > 15:
        # scientific
        mant = digits[0] + ("." + digits[1:] if L > 1 else "")
        e = D - 1
        return f"{sign}{mant}e{e:+03d}"
    if D <= 0:
        return sign + "0." + "0" * (-D) + digits
    if D >= L:
        return sign + digits + "0" * (D - L)
    return sign + digits[:D] + "." + digits[D:]

def number_to_string(v):
    if v.lit is not None:
        return v.lit
    return format_plain_double(v.f)

# ---------------- UTF-8 sanitize / string decode ----------------
def sanitize_utf8_bytes(data: bytes) -> str:
    out = []
    i = 0
    n = len(data)
    while i < n:
        b = data[i]
        if b < 0x80:
            out.append(chr(b)); i += 1; continue
        if 0xC2 <= b <= 0xDF:
            need = 1
        elif 0xE0 <= b <= 0xEF:
            need = 2
        elif 0xF0 <= b <= 0xF4:
            need = 3
        elif b in (0xC0, 0xC1):
            out.append("\ufffd"); i += 1; continue
        else:
            out.append("\ufffd"); i += 1; continue
        # collect continuations
        j = i + 1
        got = 0
        while got < need and j < n and 0x80 <= data[j] <= 0xBF:
            j += 1; got += 1
        if got < need:
            out.append("\ufffd"); i = j; continue
        seq = data[i:j]
        try:
            ch = seq.decode("utf-8")
            cp = ord(ch)
            if cp > 0x10FFFF or 0xD800 <= cp <= 0xDFFF:
                out.append("\ufffd")
            else:
                out.append(ch)
        except Exception:
            out.append("\ufffd")
        i = j
    return "".join(out)

class StringDecodeError(Exception):
    def __init__(self, msg):
        super().__init__(msg)
        self.msg = msg

_HEXDIGITS = set("0123456789abcdefABCDEF")

def decode_string_content(raw: bytes, allow_controls=False) -> str:
    """raw is bytes between quotes (for JSON) - processes escapes, validates."""
    out = []
    i = 0
    n = len(raw)
    # We iterate over bytes for non-escape segments using sanitize, but need error on controls.
    seg_start = 0
    def flush_seg(end):
        if end > seg_start:
            seg = raw[seg_start:end]
            if not allow_controls:
                for bb in seg:
                    if bb < 0x20:
                        raise StringDecodeError("Invalid string: control characters from U+0000 through U+001F must be escaped")
            out.append(sanitize_utf8_bytes(seg))
    while i < n:
        b = raw[i]
        if b == 0x5C:  # backslash
            flush_seg(i)
            if i + 1 >= n:
                raise StringDecodeError("Invalid escape")
            c = chr(raw[i+1])
            if c == '"': out.append('"'); i += 2
            elif c == "\\": out.append("\\"); i += 2
            elif c == "/": out.append("/"); i += 2
            elif c == "b": out.append("\b"); i += 2
            elif c == "f": out.append("\f"); i += 2
            elif c == "n": out.append("\n"); i += 2
            elif c == "r": out.append("\r"); i += 2
            elif c == "t": out.append("\t"); i += 2
            elif c == "u":
                hexpart = raw[i+2:i+6]
                if len(hexpart) < 4:
                    raise StringDecodeError("Invalid \\uXXXX escape")
                try:
                    hs = hexpart.decode("ascii")
                except Exception:
                    raise StringDecodeError("Invalid characters in \\uXXXX escape")
                if any(ch not in _HEXDIGITS for ch in hs):
                    raise StringDecodeError("Invalid characters in \\uXXXX escape")
                code = int(hs, 16)
                i += 6
                if 0xD800 <= code <= 0xDBFF:
                    # need low surrogate
                    if i + 6 <= n and raw[i:i+2] == b"\\u":
                        hex2 = raw[i+2:i+6]
                        try:
                            hs2 = hex2.decode("ascii")
                        except Exception:
                            hs2 = ""
                        if len(hs2) == 4 and all(ch in _HEXDIGITS for ch in hs2):
                            code2 = int(hs2, 16)
                            if 0xDC00 <= code2 <= 0xDFFF:
                                cp = 0x10000 + ((code - 0xD800) << 10) + (code2 - 0xDC00)
                                out.append(chr(cp)); i += 6; seg_start = i; continue
                    raise StringDecodeError("Invalid \\uXXXX\\uXXXX surrogate pair escape")
                elif 0xDC00 <= code <= 0xDFFF:
                    out.append("\ufffd")
                else:
                    out.append(chr(code))
            else:
                raise StringDecodeError("Invalid escape")
            seg_start = i
        else:
            i += 1
    flush_seg(n)
    return "".join(out)

def decode_string_content_str(raw: str, allow_controls=True) -> str:
    # For filter source (str). Convert surrogateescape chars to bytes then decode.
    # Raw controls allowed in filter strings.
    try:
        b = raw.encode("utf-8", "surrogateescape")
    except Exception:
        b = raw.encode("utf-8", "replace")
    return decode_string_content(b, allow_controls=allow_controls)

# ---------------- JSON dump ----------------
DEFAULT_COLORS = ["0;90", "0;39", "0;39", "0;39", "0;32", "1;39", "1;39", "1;34"]

def parse_jq_colors(envval):
    colors = list(DEFAULT_COLORS)
    if envval is None:
        return colors, True
    parts = envval.split(":")
    # validate each non-empty part chars digits/semicolon
    for p in parts:
        if p == "":
            continue
        if not re.fullmatch(r"[0-9;]+", p):
            return list(DEFAULT_COLORS), False
    for idx, p in enumerate(parts[:8]):
        if p != "":
            colors[idx] = p
    return colors, True

def escape_string(s: str, ascii_only=False) -> str:
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == "\\":
            out.append("\\\\")
        elif ch == "\b":
            out.append("\\b")
        elif ch == "\f":
            out.append("\\f")
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif o < 0x20 or o == 0x7F:
            out.append("\\u%04x" % o)
        elif ascii_only and o > 0x7F:
            if o <= 0xFFFF:
                out.append("\\u%04x" % o)
            else:
                cp = o - 0x10000
                hi = 0xD800 + (cp >> 10); lo = 0xDC00 + (cp & 0x3FF)
                out.append("\\u%04x\\u%04x" % (hi, lo))
        else:
            # lone surrogates shouldn't occur; replace
            if 0xD800 <= o <= 0xDFFF:
                out.append("\ufffd")
            else:
                out.append(ch)
    out.append('"')
    return "".join(out)

class DumpOpts:
    __slots__ = ("compact", "indent", "sort_keys", "ascii", "color", "colors")
    def __init__(self, compact=False, indent=2, sort_keys=False, ascii_only=False, color=False, colors=None):
        self.compact = compact
        self.indent = indent  # -1 tab, else spaces count
        self.sort_keys = sort_keys
        self.ascii = ascii_only
        self.color = color
        self.colors = colors if colors is not None else list(DEFAULT_COLORS)
    def indent_str(self, level):
        if self.compact:
            return ""
        if self.indent == -1:
            return "\t" * level
        return " " * (self.indent * level)

def _colorize(opts, idx, text):
    if not opts.color:
        return text
    code = opts.colors[idx]
    return f"\x1b[{code}m{text}\x1b[0m"

def dump_value(v, opts: DumpOpts, level=0) -> str:
    if v is None:
        return _colorize(opts, 0, "null")
    if v is True:
        return _colorize(opts, 2, "true")
    if v is False:
        return _colorize(opts, 1, "false")
    if isinstance(v, JNum):
        s = number_to_string(v)
        if s == "null":  # nan dumps as null (null color? jq dumps number nan as null token; color likely number? test later) use number color
            return _colorize(opts, 3, s) if opts.color else s
        return _colorize(opts, 3, s)
    if isinstance(v, str):
        return _colorize(opts, 4, escape_string(v, opts.ascii))
    if isinstance(v, list):
        if len(v) == 0:
            return _colorize(opts, 5, "[]")
        if opts.compact:
            inner = _colorize(opts, 5, ",").join(dump_value(x, opts, level+1) for x in v) if opts.color else ",".join(dump_value(x, opts, level+1) for x in v)
            # The above join with colorized comma: join inserts that between; okay
            return _colorize(opts, 5, "[") + inner + _colorize(opts, 5, "]")
        else:
            parts = [_colorize(opts, 5, "[")]
            for i, x in enumerate(v):
                parts.append("\n" + opts.indent_str(level+1) + dump_value(x, opts, level+1))
                if i < len(v) - 1:
                    parts.append(_colorize(opts, 5, ","))
            parts.append("\n" + opts.indent_str(level) + _colorize(opts, 5, "]"))
            return "".join(parts)
    if isinstance(v, dict):
        if len(v) == 0:
            return _colorize(opts, 6, "{}")
        keys = sorted(v.keys()) if opts.sort_keys else list(v.keys())
        if opts.compact:
            segs = []
            for k in keys:
                segs.append(_colorize(opts, 7, escape_string(k, opts.ascii)) + _colorize(opts, 6, ":") + dump_value(v[k], opts, level+1))
            joiner = _colorize(opts, 6, ",") if opts.color else ","
            return _colorize(opts, 6, "{") + joiner.join(segs) + _colorize(opts, 6, "}")
        else:
            parts = [_colorize(opts, 6, "{")]
            for i, k in enumerate(keys):
                parts.append("\n" + opts.indent_str(level+1) + _colorize(opts, 7, escape_string(k, opts.ascii)) + _colorize(opts, 6, ":") + " " + dump_value(v[k], opts, level+1))
                if i < len(keys) - 1:
                    parts.append(_colorize(opts, 6, ","))
            parts.append("\n" + opts.indent_str(level) + _colorize(opts, 6, "}"))
            return "".join(parts)
    return "null"

_COMPACT_OPTS = DumpOpts(compact=True)

def tojson_compact(v):
    return dump_value(v, _COMPACT_OPTS)

def short_dump(v):
    s = tojson_compact(v)
    b = s.encode("utf-8", "replace")
    if len(b) > 14:
        return b[:11].decode("utf-8", "ignore") + "..."
    return s

def value_desc(v):
    return f"{type_name(v)} ({short_dump(v)})"

def tostring_value(v):
    if isinstance(v, str):
        return v
    return tojson_compact(v)

