# ---------------- JSON parser ----------------
class ParseError(Exception):
    def __init__(self, msg, line, col, at_eof=False, from_eof=False):
        super().__init__(msg)
        self.msg = msg
        self.line = line
        self.col = col
        self.at_eof = at_eof
        self.from_eof = from_eof
    @property
    def display(self):
        return f"{self.msg}{' at EOF' if self.at_eof else ''} at line {self.line}, column {self.col}"

class _Frame:
    __slots__ = ("kind", "value", "state", "pending_key", "candidate", "next_index", "last_key", "has_children", "pending_leaf", "incoming_key")
    def __init__(self, kind, incoming_key=None):
        self.kind = kind
        self.value = [] if kind == "array" else {}
        self.state = "value_or_end" if kind == "array" else "key_or_end"
        self.pending_key = None
        self.candidate = None
        self.next_index = 0
        self.last_key = None
        self.has_children = False
        self.pending_leaf = None
        self.incoming_key = incoming_key

_BARE_DELIMS = set(b" \t\r\n[]{},:\"")

class JsonParser:
    def __init__(self, stream=False, stream_errors=False, seq=False, seq_warn=None):
        self.stream = stream or stream_errors
        self.stream_errors = stream_errors
        self.seq = seq
        self.seq_warn = seq_warn or (lambda s: None)
        self.buffer = bytearray()
        self.bpos = 0
        self.line = 1
        self.col = 0
        self.pos = 0  # global bytes consumed
        self.mode = "between"  # between|string|bare
        self.string_raw = bytearray()
        self.string_escape = False
        self.bare_raw = bytearray()
        self.bare_end_line = 1
        self.bare_end_pos = 0
        self.stack = []
        self.queue = []  # list of (value, end_offset, conv_line)
        self.pending_error = None
        self.finished = False
        self.dead = False
        self.seq_state = "abandoned" if seq else "active"
        self.top_start_pos = None

    # ----- utility -----
    def _err(self, msg, at_eof=False, from_eof=False):
        raise ParseError(msg, self.line, self.col, at_eof=at_eof, from_eof=from_eof)

    def _reset_clean(self):
        self.mode = "between"
        self.string_raw = bytearray(); self.string_escape = False
        self.bare_raw = bytearray()
        self.stack = []
        self.top_start_pos = None

    def reset_after_error(self):
        self.pending_error = None
        self._reset_clean()
        if self.seq:
            self.seq_state = "resync"

    def _current_path(self):
        path = []
        for fr in self.stack:
            if fr.incoming_key is not None:
                path.append(fr.incoming_key)
        if self.stack:
            fr = self.stack[-1]
            if fr.kind == "array":
                path.append(N(fr.next_index))
            else:
                if fr.pending_key is not None:
                    path.append(fr.pending_key)
                elif isinstance(fr.candidate, str):
                    path.append(fr.candidate)
        return path

    def _handle_error(self, err: ParseError):
        if self.seq and not self.stream_errors:
            suffix = "" if err.from_eof else " (need RS to resync)"
            self.seq_warn(f"jq: ignoring parse error: {err.display}{suffix}\n")
            self._reset_clean()
            if err.from_eof:
                self.finished = True
            else:
                self.seq_state = "resync"
            return True
        if self.stream_errors:
            ev = [err.display, self._current_path()]
            self.queue.append((ev, self.pos, self.line))
            self.dead = True
            self._reset_clean()
            return False
        self.pending_error = err
        return False

    def feed(self, data: bytes):
        if data:
            self.buffer += data
        self._process()

    def finish(self):
        if self.finished or self.dead or self.pending_error is not None:
            self.finished = True
            return
        # process any remaining buffered bytes first
        self._process()
        if self.pending_error is not None or self.dead:
            self.finished = True
            return
        try:
            if self.seq:
                self._finish_seq()
            else:
                self._finish_normal()
        except ParseError as e:
            e.from_eof = True
            self._handle_error(e)
        self.finished = True

    def _finish_normal(self):
        if self.mode == "bare":
            self._finish_bare(at_eof=True)
            if self.stack:
                self._err("Unfinished JSON term at EOF", from_eof=True)
        elif self.mode == "string":
            self._err("Unfinished string at EOF", from_eof=True)
        elif self.stack:
            self._err("Unfinished JSON term at EOF", from_eof=True)

    def _finish_seq(self):
        if self.seq_state == "abandoned":
            self.seq_warn(f"jq: ignoring parse error: Unfinished abandoned text at EOF at line {self.line}, column {self.col}\n")
            return
        if self.seq_state == "resync":
            return
        # active
        if self.mode == "bare":
            # Decide potentially truncated numeric
            raw = bytes(self.bare_raw)
            val = None; is_num_token = False; ok = False
            try:
                val, is_num_token = self._parse_bare(raw)
                ok = True
            except ParseError:
                ok = False
            if ok and not self.stack and is_num_token:
                self.seq_warn(f"jq: ignoring parse error: Potentially truncated top-level numeric value at EOF at line {self.line}, column {self.col}\n")
                self._reset_clean(); return
            # otherwise normal finish (validate/queue or error via _finish_normal logic but warnings)
            try:
                self._finish_bare(at_eof=True)
                if self.stack:
                    self._err("Unfinished JSON term at EOF", from_eof=True)
            except ParseError as e:
                e.from_eof = True
                self.seq_warn(f"jq: ignoring parse error: {e.display}\n")
                self._reset_clean()
            return
        if self.mode == "string":
            self.seq_warn(f"jq: ignoring parse error: Unfinished string at EOF at line {self.line}, column {self.col}\n")
            self._reset_clean(); return
        if self.stack:
            self.seq_warn(f"jq: ignoring parse error: Unfinished JSON term at EOF at line {self.line}, column {self.col}\n")
            self._reset_clean(); return

    def _process(self):
        while self.bpos < len(self.buffer):
            if self.pending_error is not None or self.dead:
                break
            b = self.buffer[self.bpos]
            self.bpos += 1
            self.pos += 1
            prev_line = self.line
            if b == 0x0A:
                self.line += 1; self.col = 0
            else:
                self.col += 1
            try:
                self._dispatch(b, prev_line)
            except ParseError as e:
                cont = self._handle_error(e)
                if not cont:
                    break
                # seq: continue processing (in resync mode)
        # compact buffer
        if self.bpos > 0:
            del self.buffer[:self.bpos]
            self.bpos = 0

    def _dispatch(self, b, prev_line):
        if self.seq:
            if self.seq_state in ("abandoned", "resync"):
                if b == 0x1E:
                    self.seq_state = "active"
                    self._reset_clean()
                return
            if b == 0x1E:
                # active
                if self.mode == "between" and not self.stack:
                    return
                # truncated
                if self.mode == "bare" and not self.stack:
                    # numeric?
                    raw = bytes(self.bare_raw)
                    is_num = False
                    try:
                        _v, is_num = self._parse_bare(raw)
                    except ParseError:
                        # determine classifier: if first char t/f or startswith nu -> not numeric
                        s = raw.decode("utf-8", "replace")
                        is_num = not (s[:1] in "tf" or s.startswith("nu"))
                    if is_num:
                        self.seq_warn(f"jq: ignoring parse error: Potentially truncated top-level numeric value at line {self.line}, column {self.col}\n")
                    else:
                        self.seq_warn(f"jq: ignoring parse error: Truncated value at line {self.line}, column {self.col}\n")
                else:
                    self.seq_warn(f"jq: ignoring parse error: Truncated value at line {self.line}, column {self.col}\n")
