                if b in b" \t\r\n":
                    return
                self._between_byte(b)
                return
            else:
                self.bare_raw.append(b)
                self.bare_end_line = self.line if b != 0x0A else prev_line
                self.bare_end_pos = self.pos
                return
        # between
        self._between_byte(b)

    def _between_byte(self, b):
        if b in b" \t\r\n":
            return
        if not self.stack and self.top_start_pos is None and b not in b"],}:":
            # a value is starting at top (approx)
            self.top_start_pos = self.pos - 1
        if b == 0x22:  # "
            self.mode = "string"
            self.string_raw = bytearray(); self.string_escape = False
            return
        if b == 0x5B:  # [
            self._push_frame("array")
            return
        if b == 0x7B:  # {
            self._push_frame("object")
            return
        if b == 0x5D:  # ]
            self._close_array()
            return
        if b == 0x7D:  # }
            self._close_object()
            return
        if b == 0x2C:  # ,
            self._comma()
            return
        if b == 0x3A:  # :
            self._colon()
            return
        if b == 0x27:
            # single quote starts a bare token (will error as invalid string literal)
            pass
        # bare token start
        self.mode = "bare"
        self.bare_raw = bytearray([b])
        self.bare_end_line = self.line
        self.bare_end_pos = self.pos

    def _incoming_key_for_new_frame(self):
        if not self.stack:
            return None
        fr = self.stack[-1]
        if fr.kind == "array":
            return N(fr.next_index)
        else:
            if fr.state == "value":
                return fr.pending_key
            return None

    def _push_frame(self, kind):
        fr = _Frame(kind, incoming_key=self._incoming_key_for_new_frame())
        self.stack.append(fr)

    def _string_byte(self, b):
        if self.string_escape:
            self.string_raw.append(b)
            self.string_escape = False
            return
        if b == 0x5C:
            self.string_raw.append(b)
            self.string_escape = True
            return
        if b == 0x22:
            raw = bytes(self.string_raw)
            self.mode = "between"; self.string_raw = bytearray()
            try:
                s = decode_string_content(raw, allow_controls=False)
            except StringDecodeError as e:
                self._err(e.msg)
            self._place_child(True, s, self.pos, self.line)
            return
        self.string_raw.append(b)

    def _parse_bare(self, raw: bytes):
        """Returns (value, is_numeric_token). Raises ParseError (without location override)."""
        eff = raw
        nul = eff.find(b"\x00")
        if nul >= 0:
            eff = eff[:nul]
        if len(eff) == 0:
            self._err("Invalid numeric literal")
        s = eff.decode("utf-8", "replace")
        if s and s[0] == "'":
            self._err("Invalid string literal; expected \", but got '")
        if s and s[0] == "t":
            if s == "true":
                return True, False
            self._err("Invalid literal")
        if s and s[0] == "f":
            if s == "false":
                return False, False
            self._err("Invalid literal")
        if s.startswith("nu"):
            if s == "null":
                return None, False
            self._err("Invalid literal")
