    def _frame_path(self, upto_index):
        """Path (list) to frame at stack index upto_index (its incoming location)"""
        path = []
        for fr in self.stack[:upto_index+1]:
            if fr.incoming_key is not None:
                path.append(fr.incoming_key)
        return path

    def _place_child(self, is_leaf, val, end_pos, end_line, placeholder=None):
        # after a child (scalar or container) completes; stack top is parent (child frame already popped for containers)
        if not self.stack:
            if self.stream:
                if is_leaf:
                    self.queue.append(([ [], val], end_pos, end_line))
                # non-leaf top: events already emitted
            else:
                self.queue.append((val, end_pos, end_line))
            self.top_start_pos = None
            return
        fr = self.stack[-1]
        if fr.kind == "array":
            if fr.state in ("value_or_end", "value"):
                key = N(fr.next_index)
                fr.next_index += 1
                fr.last_key = key
                fr.has_children = True
                fr.state = "sep"
                if self.stream:
                    if is_leaf:
                        fr.pending_leaf = (key, val, end_pos, end_line)
                    else:
                        fr.pending_leaf = None
                else:
                    fr.value.append(val)
                return
            else:
