                fr.candidate = val if is_leaf else (placeholder if placeholder is not None else [])
                fr.state = "colon"
                return
            if fr.state == "value":
                key = fr.pending_key
                fr.last_key = key
                fr.has_children = True
                fr.state = "sep"
                fr.pending_key = None
                if self.stream:
                    if is_leaf:
                        fr.pending_leaf = (key, val, end_pos, end_line)
                    else:
                        fr.pending_leaf = None
                else:
                    fr.value[key] = val
                return
            else:
                self._err("Expected separator between values")

    def _flush_pending(self, frame_index):
        fr = self.stack[frame_index]
        if fr.pending_leaf is not None:
            key, val, end_pos, end_line = fr.pending_leaf
            fr.pending_leaf = None
            path = self._frame_path(frame_index) + [key]
            self.queue.append(([path, val], end_pos, end_line))

    def _comma(self):
