                return
            else:
                self._err("Expected another array element")
        else:
            if fr.state == "sep":
                if self.stream:
                    self._flush_pending(len(self.stack)-1)
                fr.state = "key"
                return
            if fr.state == "colon":
                self._err("Objects must consist of key:value pairs")
            else:
