        if fr.state == "colon":
            if not isinstance(fr.candidate, str):
                self._err("Object keys must be strings")
            fr.pending_key = fr.candidate
            fr.candidate = None
            fr.state = "value"
            return
        if fr.state in ("key_or_end", "key"):
            self._err("Expected string key before ':'")
        self._err("':' not as part of an object")

    def _unmatched(self, ch):
        if self.stream:
            if not self.stack:
                self._err(f"Unmatched '{ch}' at the top-level")
            elif self.stack[-1].kind == "array":
                self._err(f"Unmatched '{ch}' in the middle of an array")
            else:
                self._err(f"Unmatched '{ch}' in the middle of an object")
        else:
            self._err(f"Unmatched '{ch}'")

    def _close_array(self):
        if not self.stack or self.stack[-1].kind != "array":
            self._unmatched("]")
        fr = self.stack[-1]
        if fr.state == "value":
            self._err("Expected another array element")
        # pop
        idx = len(self.stack) - 1
        if self.stream:
            if not fr.has_children:
                self.stack.pop()
                self._place_child(True, [], self.pos, self.line)
            else:
                self._flush_pending(idx)
                trunc_path = self._frame_path(idx) + [fr.last_key]
                self.queue.append(([trunc_path], self.pos, self.line))
                self.stack.pop()
                self._place_child(False, None, self.pos, self.line, placeholder=[])
        else:
            val = fr.value
            self.stack.pop()
            self._place_child(True, val, self.pos, self.line)

    def _close_object(self):
        if not self.stack or self.stack[-1].kind != "object":
            self._unmatched("}")
        fr = self.stack[-1]
        if fr.state == "key":
            self._err("Expected another key-value pair")
        if fr.state == "colon":
            self._err("Objects must consist of key:value pairs")
        if fr.state == "value":
            if self.stream:
                self._err("Missing value in key:value pair")
            else:
                self._err("Unmatched '}'")
