                self.stack.pop()
                self._place_child(False, None, self.pos, self.line, placeholder={})
        else:
            val = fr.value
            self.stack.pop()
            self._place_child(True, val, self.pos, self.line)

    def has_value(self):
        return len(self.queue) > 0
    def pop_value(self):
        return self.queue.pop(0)

