            return
        if b == 0x7B:  # {
            self._push_frame("object")
            return
        if b == 0x5D:  # ]
            self._close_array()
            return
        if b == 0x7D:  # }
            self._close_object()
            return
        if b == 0x2C:  # ,
            self._comma()
            return
        if b == 0x3A:  # :
            self._colon()
            return
        if b == 0x27:
            # single quote starts a bare token (will error as invalid string literal)
            pass
