            self._err("Invalid literal")
        if s and s[0] == "f":
            if s == "false":
                return False, False
            self._err("Invalid literal")
        if s.startswith("nu"):
            if s == "null":
                return None, False
            self._err("Invalid literal")
        num = make_literal_number(s)
