                self._err(f"Unmatched '{ch}' at the top-level")
            elif self.stack[-1].kind == "array":
                self._err(f"Unmatched '{ch}' in the middle of an array")
            else:
                self._err(f"Unmatched '{ch}' in the middle of an object")
        else:
