        idx = len(self.stack) - 1
        if self.stream:
            if not fr.has_children:
                self.stack.pop()
                self._place_child(True, [], self.pos, self.line)
            else:
                self._flush_pending(idx)
                trunc_path = self._frame_path(idx) + [fr.last_key]
