                self.stack.pop()
                self._place_child(False, None, self.pos, self.line, placeholder=[])
        else:
            val = fr.value
            self.stack.pop()
            self._place_child(True, val, self.pos, self.line)

    def _close_object(self):
        if not self.stack or self.stack[-1].kind != "object":
            self._unmatched("}")
        fr = self.stack[-1]
        if fr.state == "key":
            self._err("Expected another key-value pair")
        if fr.state == "colon":
            self._err("Objects must consist of key:value pairs")
        if fr.state == "value":
            if self.stream:
