        else:
            val = fr.value
            self.stack.pop()
            self._place_child(True, val, self.pos, self.line)

    def has_value(self):
        return len(self.queue) > 0
    def pop_value(self):
        return self.queue.pop(0)

def parse_json_values_from_bytes(data: bytes):
    """Parse all values; raises ParseError."""
    p = JsonParser()
    p.feed(data)
    p.finish()
    if p.pending_error is not None:
        raise p.pending_error
    vals = [v for (v, _e, _l) in p.queue]
    return vals

