    """For --argjson / tonumber etc: exactly one value. Returns value or raises ValueError/ParseError."""
    data = text.encode("utf-8", "surrogateescape")
    vals = parse_json_values_from_bytes(data)
    if len(vals) != 1:
        raise ValueError("not single")
    return vals[0]

