# ---------------- Filter lexer / parser ----------------
class Source:
    def __init__(self, name, text):
        self.name = name
        self.text = text
        self.line_starts = [0]
        for i, ch in enumerate(text):
            if ch == "\n":
                self.line_starts.append(i+1)
    def linecol(self, idx):
        line = bisect.bisect_right(self.line_starts, idx)
        start = self.line_starts[line-1]
        prefix = self.text[start:idx]
        col = len(prefix.encode("utf-8", "surrogateescape")) + 1
        return line, col
    def line_text(self, line):
        if line < 1 or line > len(self.line_starts):
            return ""
        start = self.line_starts[line-1]
        end = self.text.find("\n", start)
        if end == -1:
            end = len(self.text)
        return self.text[start:end]

class CompileError:
    def __init__(self, msg, source=None, line=1, col=1, caret=1, raw=None):
        self.msg = msg; self.source = source; self.line = line; self.col = col; self.caret = caret; self.raw = raw
    def render(self):
        if self.raw is not None:
            return self.raw
        if self.source is None:
            return f"jq: error: {self.msg}\n"
        line_text = self.source.line_text(self.line)
        return (f"jq: error: {self.msg} at {self.source.name}, line {self.line}, column {self.col}:\n"
                f"    {line_text}\n"
                f"    {' ' * (self.col-1)}{'^' * max(1, self.caret)}\n")

class JqCompileException(Exception):
    def __init__(self, errors):
        super().__init__("compile error")
        self.errors = errors if isinstance(errors, list) else [errors]

def render_compile_errors(errors):
    out = "".join(e.render() for e in errors)
    n = len(errors)
    out += f"jq: {n} compile error{'s' if n != 1 else ''}\n"
    return out

class Loc:
    __slots__ = ("source", "line", "col", "start", "end")
    def __init__(self, source, line, col, start, end):
        self.source = source; self.line = line; self.col = col; self.start = start; self.end = end

class Node:
    __slots__ = ("kind", "x", "loc", "end")
    def __init__(self, kind, *x, loc=None):
        self.kind = kind; self.x = x; self.loc = loc; self.end = loc.end if loc else 0
    def __repr__(self):
        return f"Node({self.kind},{self.x!r})"

KEYWORDS = {"def","as","if","then","elif","else","end","try","catch","label","break","import","include","module","and","or","reduce","foreach"}

class Tok:
    __slots__ = ("type", "value", "text", "loc", "is_escape")
    def __init__(self, type_, value, text, loc, is_escape=False):
        self.type = type_; self.value = value; self.text = text; self.loc = loc; self.is_escape = is_escape
    def __repr__(self):
        return f"Tok({self.type},{self.text!r})"

def _is_ident_start(ch):
    return ch == "_" or ("A" <= ch <= "Z") or ("a" <= ch <= "z")
def _is_ident_char(ch):
    return _is_ident_start(ch) or ("0" <= ch <= "9")

class Lexer:
    def __init__(self, source: Source):
        self.src = source.text
        self.source = source
        self.i = 0
        self.n = len(self.src)
        # mode stack: each is [kind, paren_depth] kind normal|string|interp
        self.modes = [["normal", 0]]
        self.last_tok = None
    def _loc(self, start, end):
        line, col = self.source.linecol(start)
        return Loc(self.source, line, col, start, end)
    def _tok(self, type_, start, end, value=None, is_escape=False):
        t = Tok(type_, value, self.src[start:end], self._loc(start, end), is_escape)
        self.last_tok = t
        return t
    def _eof(self):
        if self.last_tok is not None:
            lt = self.last_tok
            t = Tok("EOF", None, lt.text, lt.loc)
            return t
        return Tok("EOF", None, "", self._loc(self.n, self.n))
    def next_token(self):
        if self.modes and self.modes[-1][0] == "string":
            return self._string_token()
        return self._normal_token()
    def _string_token(self):
        i = self.i
        if i >= self.n:
            return self._eof()
        start = i
        ch = self.src[i]
        if ch == '"':
            self.i = i + 1
            self.modes.pop()
            return self._tok("STRING_END", start, self.i)
        if ch == "\\" and i + 1 < self.n and self.src[i+1] == "(":
            self.i = i + 2
            self.modes.append(["interp", 0])
            return self._tok("INTERP_START", start, self.i)
        if ch == "\\":
            # escape chunk
            i += 1
            if i < self.n:
                c = self.src[i]; i += 1
                if c == "u":
                    cnt = 0
                    while cnt < 4 and i < self.n and self.src[i] != '"':
                        i += 1; cnt += 1
                    # check high surrogate followed by \u
                    chunk = self.src[start:i]
                    hexs = chunk[2:]
                    if len(hexs) == 4 and all(ch in _HEXDIGITS for ch in hexs):
                        code = int(hexs, 16)
                        if 0xD800 <= code <= 0xDBFF and self.src[i:i+2] == "\\u":
                            i += 2
                            cnt = 0
                            while cnt < 4 and i < self.n and self.src[i] != '"':
                                i += 1; cnt += 1
            self.i = i
            return self._tok("STRING_TEXT", start, i, is_escape=True)
        # ordinary run
        while i < self.n and self.src[i] not in '"\\':
            i += 1
        self.i = i
        return self._tok("STRING_TEXT", start, i)
    def _skip_ws(self):
        while self.i < self.n:
            ch = self.src[self.i]
            if ch in " \t\r\n":
                self.i += 1
            elif ch == "#":
                while self.i < self.n and self.src[self.i] != "\n":
                    self.i += 1
            else:
                break
    def _scan_number(self, start):
        i = self.i
        # called with self.i at start char
        if self.src[i] == ".":
            i += 1
            while i < self.n and self.src[i].isdigit() and self.src[i] in "0123456789":
                i += 1
        else:
            while i < self.n and self.src[i] in "0123456789":
                i += 1
            if i < self.n and self.src[i] == ".":
                i += 1
                while i < self.n and self.src[i] in "0123456789":
                    i += 1
        if i < self.n and self.src[i] in "eE":
            j = i + 1
            if j < self.n and self.src[j] in "+-":
                j += 1
            if j < self.n and self.src[j] in "0123456789":
                i = j
                while i < self.n and self.src[i] in "0123456789":
                    i += 1
        self.i = i
        text = self.src[start:i]
        return self._tok("NUMBER", start, i, value=text)
    def _scan_ident_ns(self, i):
        # i at ident start; returns end index
        j = i
        while j < self.n and _is_ident_char(self.src[j]):
            j += 1
        while self.src[j:j+2] == "::" and j + 2 < self.n and _is_ident_start(self.src[j+2]):
            j += 2
            while j < self.n and _is_ident_char(self.src[j]):
                j += 1
        return j
    def _normal_token(self):
        self._skip_ws()
        i = self.i
        if i >= self.n:
            return self._eof()
        start = i
        ch = self.src[i]
        in_interp = self.modes and self.modes[-1][0] == "interp"
        # string start
        if ch == '"':
            self.i = i + 1
            self.modes.append(["string", 0])
            return self._tok("STRING_START", start, self.i)
        # dot / field / recurse / number
        if ch == ".":
            if i + 1 < self.n and self.src[i+1] in "0123456789":
                return self._scan_number(start)
            if self.src[i:i+2] == "..":
                self.i = i + 2
                return self._tok("..", start, self.i)
            if i + 1 < self.n and _is_ident_start(self.src[i+1]):
                j = i + 1
                while j < self.n and _is_ident_char(self.src[j]):
                    j += 1
                self.i = j
                name = self.src[i+1:j]
                return self._tok("FIELD", start, j, value=name)
            self.i = i + 1
            return self._tok(".", start, self.i)
        if ch in "0123456789":
            return self._scan_number(start)
        if _is_ident_start(ch):
            j = self._scan_ident_ns(i)
            self.i = j
            text = self.src[start:j]
            if "::" not in text and text in KEYWORDS:
                return self._tok(text, start, j, value=text)
            if "::" not in text and text in ("true", "false", "null"):
                return self._tok("LITERALWORD", start, j, value=text)
            return self._tok("IDENT", start, j, value=text)
        if ch == "$":
            if self.src[i:i+9] == "$__loc__" and not (i+9 < self.n and (_is_ident_char(self.src[i+9]) or self.src[i+9] == ":")):
                self.i = i + 9
                return self._tok("LOC", start, self.i, value="__loc__")
            if i + 1 < self.n and _is_ident_start(self.src[i+1]):
                j = self._scan_ident_ns(i+1)
                self.i = j
                return self._tok("BINDING", start, j, value=self.src[i+1:j])
            self.i = i + 1
            return self._tok("INVALID", start, self.i)
        if ch == "@":
            if i + 1 < self.n and _is_ident_start(self.src[i+1]):
                j = i + 1
                while j < self.n and _is_ident_char(self.src[j]):
                    j += 1
                self.i = j
                return self._tok("FORMAT", start, j, value=self.src[i+1:j])
            self.i = i + 1
            return self._tok("INVALID", start, self.i)
        # multi-char operators
        for op in ("?//", "//=", "==", "!=", "<=", ">=", "//", "|=", "+=", "-=", "*=", "/=", "%="):
            if self.src[i:i+len(op)] == op:
                self.i = i + len(op)
                return self._tok(op, start, self.i)
        if ch == "(":
            self.i = i + 1
            if in_interp:
                self.modes[-1][1] += 1
            return self._tok("(", start, self.i)
        if ch == ")":
            self.i = i + 1
            if in_interp:
                if self.modes[-1][1] == 0:
                    self.modes.pop()
                    return self._tok("INTERP_END", start, self.i)
                else:
                    self.modes[-1][1] -= 1
            return self._tok(")", start, self.i)
        if ch in "|,:;[]{}?+-%<>=" or ch == "*" or ch == "/":
            self.i = i + 1
            return self._tok(ch, start, self.i)
        # invalid char
        self.i = i + 1
        return self._tok("INVALID", start, self.i)

def token_desc(tok):
    t = tok.type
    if t == "EOF":
        return "end of file"
    if t == "IDENT":
        return "IDENT"
    if t == "NUMBER":
        return "LITERAL"
    if t == "LITERALWORD":
        return "IDENT"
    if t == "STRING_START":
        return "QQSTRING_START"
    if t == "STRING_TEXT":
        return "QQSTRING_TEXT"
    if t == "STRING_END":
        return "QQSTRING_END"
    if t == "INTERP_START":
        return "QQSTRING_INTERP_START"
    if t == "INTERP_END":
        return "QQSTRING_INTERP_END"
    if t == "FIELD":
        return "FIELD"
    if t == "BINDING":
        return "BINDING"
    if t == "FORMAT":
        return "FORMAT"
    if t == "LOC":
        return "$__loc__"
    if t == "INVALID":
        return "INVALID_CHARACTER"
    if t in KEYWORDS:
        return t
    # operators: quoted for some, bare for others
    if t in ("|", ",", ":", ";", "(", ")", "[", "]", "{", "}", "?", "+", "<", ">", "=", "."):
        return f"'{t}'"
    return t

class Program:
    __slots__ = ("source", "meta", "imports", "expr", "defs", "is_library", "name_for_meta")
    def __init__(self, source):
        self.source = source
        self.meta = None
        self.imports = []
        self.expr = None
        self.defs = []  # list of Node funcdef (library)
        self.is_library = False
        self.name_for_meta = None

class Parser:
    def __init__(self, source: Source):
        self.source = source
        self.lexer = Lexer(source)
        self.buf = []
    # token helpers
    def _fill(self, n):
        while len(self.buf) <= n:
            self.buf.append(self.lexer.next_token())
    def peek(self, n=0):
        self._fill(n)
        return self.buf[n]
    def next(self):
        t = self.peek(0)
        del self.buf[0]
        return t
    def at(self, type_):
        return self.peek().type == type_
    def accept(self, type_):
        if self.at(type_):
            return self.next()
        return None
    def syntax_error(self, tok=None, expecting=None, msg=None):
        tok = tok or self.peek()
        if msg is None:
            msg = f"syntax error, unexpected {token_desc(tok)}"
            if expecting:
                msg += f", expecting {expecting}"
        caret = len(tok.text.encode("utf-8", "surrogateescape")) or 1
        err = CompileError(msg, tok.loc.source, tok.loc.line, tok.loc.col, caret)
        raise JqCompileException([err])
    def expect(self, type_, expecting=None):
        if self.at(type_):
            return self.next()
        self.syntax_error(expecting=expecting or token_desc_for_expect(type_))

def token_desc_for_expect(type_):
    if type_ == "EOF":
        return "end of file"
    if type_ in ("|", ",", ":", ";", "(", ")", "[", "]", "{", "}", "?", "+", "<", ">", "=", "."):
        return f"'{type_}'"
    if type_ == "STRING_START":
        return "QQSTRING_START"
    if type_ == "INTERP_END":
        return "QQSTRING_INTERP_END"
