def _p_parse_assign(self):
    left = self.parse_or()
    if self.peek().type in _ASSIGN_OPS:
        optok = self.next()
        rhs = self.parse_or()
        kind, op = _ASSIGN_OPS[optok.type]
        if self.peek().type in _ASSIGN_OPS:
            self.syntax_error()
        if kind == "assign":
            return self._finish(Node("assign", left, rhs, loc=left.loc))
        if kind == "update":
            return self._finish(Node("update", left, rhs, loc=left.loc))
        return self._finish(Node("compound", op, left, rhs, loc=left.loc))
    return left
Parser.parse_assign = _p_parse_assign

def _p_parse_or(self):
    left = self.parse_and()
    while self.at("or"):
        self.next()
        right = self.parse_and()
        left = self._finish(Node("binop", "or", left, right, loc=left.loc))
    return left
Parser.parse_or = _p_parse_or

def _p_parse_and(self):
    left = self.parse_compare()
    while self.at("and"):
        self.next()
        right = self.parse_compare()
        left = self._finish(Node("binop", "and", left, right, loc=left.loc))
    return left
Parser.parse_and = _p_parse_and

_CMP_OPS = ("==", "!=", "<", ">", "<=", ">=")

def _p_parse_compare(self):
    left = self.parse_add()
    if self.peek().type in _CMP_OPS:
        op = self.next().type
        right = self.parse_add()
        if self.peek().type in _CMP_OPS:
            self.syntax_error()
        return self._finish(Node("binop", op, left, right, loc=left.loc))
    return left
Parser.parse_compare = _p_parse_compare

def _p_parse_add(self):
    left = self.parse_mul()
    while self.peek().type in ("+", "-"):
        op = self.next().type
        right = self.parse_mul()
        left = self._finish(Node("binop", op, left, right, loc=left.loc))
    return left
Parser.parse_add = _p_parse_add

def _p_parse_mul(self):
    left = self.parse_unary()
    while self.peek().type in ("*", "/", "%"):
        op = self.next().type
        right = self.parse_unary()
        left = self._finish(Node("binop", op, left, right, loc=left.loc))
    return left
Parser.parse_mul = _p_parse_mul

def _p_parse_unary(self):
    if self.at("-"):
        mtok = self.next()
        operand = self.parse_unary()
        return self._finish(Node("neg", operand, loc=mtok.loc))
    return self.parse_postfix()
Parser.parse_unary = _p_parse_unary

def _p_parse_postfix(self):
    node, dot_identity, suffixes = self.parse_primary_info()
    current_base = node
    pending = list(suffixes)
    current = node
    def flush():
        nonlocal current, current_base, pending
        if pending:
            current = self._finish(Node("postfix", current_base, list(pending), loc=current_base.loc))
            pending = []
            current_base = current
        else:
            current = current_base
    first = True
    while True:
        if first and dot_identity and (self.at("STRING_START") or self.at("FORMAT")):
            # . "str" / .@fmt "str"
            if self.at("FORMAT") and self.peek(1).type != "STRING_START":
                break
            strnode = self.parse_string_or_format()
            pending.append(("index", strnode))
            dot_identity = False
            first = False
            continue
        first = False
        if self.at("FIELD"):
            pending.append(("field", self.next().value))
            continue
        if self.at("."):
            dtok = self.next()
            if self.at("STRING_START") or self.at("FORMAT"):
                if self.at("FORMAT") and self.peek(1).type != "STRING_START":
                    ft = self.peek()
                    self.syntax_error(tok=ft, expecting="QQSTRING_START")
                strnode = self.parse_string_or_format()
                pending.append(("index", strnode))
                continue
            if self.at("["):
                pending.append(self.parse_bracket_suffix(allow_slice=False))
                continue
            self.syntax_error(expecting="FORMAT or QQSTRING_START or '['")
        if self.at("["):
            pending.append(self.parse_bracket_suffix(allow_slice=True))
            continue
        if self.at("?"):
            self.next()
            flush()
            current = self._finish(Node("try", current, None, loc=current.loc))
            current_base = current
            continue
        break
    flush()
    return current
Parser.parse_postfix = _p_parse_postfix

def _p_parse_bracket_suffix(self, allow_slice=True):
    self.expect("[")
    if self.accept("]"):
        return ("iter",)
    if self.at(":"):
        if not allow_slice:
            self.syntax_error(expecting="'|' or ',' or ']'")
        self.next()
        if self.at("]"):
            self.syntax_error()
        end = self.parse_exp()
        self.expect("]", expecting="']'")
        return ("slice", None, end)
    first = self.parse_exp()
    if self.at(":"):
        if not allow_slice:
            self.syntax_error(expecting="'|' or ',' or ']'")
        self.next()
        if self.at("]"):
            end = None
        else:
            end = self.parse_exp()
        self.expect("]", expecting="']'")
        return ("slice", first, end)
    self.expect("]", expecting="']'")
    return ("index", first)
Parser.parse_bracket_suffix = _p_parse_bracket_suffix

def _p_parse_primary_info(self):
    tok = self.peek()
    t = tok.type
    if t == "NUMBER":
        self.next()
        num = make_literal_number(tok.value)
        return (Node("lit", num, loc=tok.loc), False, [])
    if t == "LITERALWORD":
        self.next()
        v = {"true": True, "false": False, "null": None}[tok.value]
        return (Node("lit", v, loc=tok.loc), False, [])
    if t == "STRING_START":
        return (self.parse_string_literal(), False, [])
    if t == "FORMAT":
        ftok = self.next()
        if self.at("STRING_START"):
            return (self.parse_string_literal(fmt=ftok.value), False, [])
        return (Node("format", ftok.value, loc=ftok.loc), False, [])
    if t == "BINDING":
        self.next()
        return (Node("var", tok.value, loc=tok.loc), False, [])
    if t == "LOC":
        self.next()
        return (Node("loc", loc=tok.loc), False, [])
    if t == "FIELD":
        self.next()
        ident = Node("identity", loc=tok.loc)
        return (ident, False, [("field", tok.value)])
    if t == ".":
        self.next()
        return (Node("identity", loc=tok.loc), True, [])
    if t == "..":
        self.next()
        return (Node("call", "recurse", [], loc=tok.loc), False, [])
    if t == "(":
        self.next()
        if self.at(")"):
            self.syntax_error()
        e = self.parse_exp()
        self.expect(")", expecting="')'")
        return (e, False, [])
    if t == "[":
        ltok = self.next()
        if self.accept("]"):
            node = Node("array", None, loc=ltok.loc)
        else:
            e = self.parse_exp()
            self.expect("]", expecting="']'")
            node = Node("array", e, loc=ltok.loc)
        return (self._finish(node), False, [])
    if t == "{":
        return (self.parse_object(), False, [])
    if t == "IDENT":
        ntok = self.next()
        name = ntok.value
        args = []
        if self.at("("):
            self.next()
            args.append(self.parse_exp())
            while self.accept(";"):
                args.append(self.parse_exp())
            self.expect(")", expecting="')'")
        return (self._finish(Node("call", name, args, loc=ntok.loc)), False, [])
    if t == "if":
        return (self.parse_if(), False, [])
    if t == "try":
        return (self.parse_try(), False, [])
    if t in ("reduce", "foreach"):
        return (self.parse_reduce_for(), False, [])
    if t == "break":
        btok = self.next()
        if not self.at("BINDING"):
            self.syntax_error(expecting="BINDING")
        name = self.next().value
        # Note: break node covers 'break $name' for error location of undefined label
        node = Node("break", name, loc=btok.loc)
        return (self._finish(node), False, [])
    self.syntax_error()
Parser.parse_primary_info = _p_parse_primary_info

def _p_parse_if(self):
    itok = self.expect("if")
    branches = []
    cond = self.parse_exp()
    if not self.accept("then"):
        self.syntax_error(expecting="then or '|' or ','")
    branches.append((cond, self.parse_exp()))
    while self.at("elif"):
        self.next()
        c = self.parse_exp()
        if not self.accept("then"):
            self.syntax_error(expecting="then or '|' or ','")
        branches.append((c, self.parse_exp()))
    else_node = None
    if self.accept("else"):
        else_node = self.parse_exp()
    if not self.accept("end"):
        self.syntax_error(expecting="end")
    return self._finish(Node("if", branches, else_node, loc=itok.loc))
Parser.parse_if = _p_parse_if

def _p_parse_try(self):
    ttok = self.expect("try")
    body = self.parse_unary()
    catch = None
    if self.accept("catch"):
        catch = self.parse_unary()
    return self._finish(Node("try", body, catch, loc=ttok.loc))
Parser.parse_try = _p_parse_try

def _p_parse_reduce_for(self):
    ktok = self.next()
    kind = ktok.type
    source = self.parse_alt()
    if not self.accept("as"):
        self.syntax_error(expecting="as")
    patterns = self.parse_patterns()
    self.expect("(", expecting="'('")
    init = self.parse_exp()
    self.expect(";", expecting="';'")
    update = self.parse_exp()
    extract = None
    if self.accept(";"):
        extract = self.parse_exp()
    self.expect(")", expecting="')'")
    if kind == "reduce":
        return self._finish(Node("reduce", source, patterns, init, update, loc=ktok.loc))
    else:
        return self._finish(Node("foreach", source, patterns, init, update, extract, loc=ktok.loc))
Parser.parse_reduce_for = _p_parse_reduce_for

def _p_parse_patterns(self):
    pats = [self.parse_pattern()]
    while self.accept("?//"):
        pats.append(self.parse_pattern())
    return pats
Parser.parse_patterns = _p_parse_patterns

def _p_parse_pattern(self):
    tok = self.peek()
    if tok.type == "BINDING":
        self.next()
        return ("var", tok.value, tok.loc)
    if tok.type == "[":
        self.next()
        pats = [self.parse_pattern()]
        while self.accept(","):
            pats.append(self.parse_pattern())
        self.expect("]", expecting="']'")
        return ("array", pats, tok.loc)
    if tok.type == "{":
        self.next()
        entries = []
        while True:
            entries.append(self.parse_pattern_object_entry())
            if self.accept(","):
                if self.at("}"):
                    break
                continue
            break
        self.expect("}", expecting="'}'")
        return ("object", entries, tok.loc)
    self.syntax_error(expecting("BINDING or '[' or '{'") if False else "BINDING or '[' or '{'")
Parser.parse_pattern = _p_parse_pattern

def _p_parse_pattern_object_entry(self):
    tok = self.peek()
    if tok.type == "BINDING":
        self.next()
        if self.accept(":"):
            sub = self.parse_pattern()
            return ("var", tok.value, sub, tok.loc)
        return ("var", tok.value, ("var", tok.value, tok.loc), tok.loc)
    if tok.type in ("IDENT", "LITERALWORD") or tok.type in KEYWORDS:
        self.next()
        name = tok.value if tok.type != "IDENT" and tok.value else tok.text
        if tok.type == "IDENT" or tok.type == "LITERALWORD":
            name = tok.value
        else:
            name = tok.text
        if not self.accept(":"):
            self.syntax_error(expecting="':'")
        sub = self.parse_pattern()
        return ("name", name, sub, tok.loc)
    if tok.type == "STRING_START" or tok.type == "FORMAT":
        strnode = self.parse_string_or_format()
        if not self.accept(":"):
            self.syntax_error(expecting="':'")
        sub = self.parse_pattern()
        return ("str", strnode, sub, tok.loc)
    if tok.type == "(":
        self.next()
        e = self.parse_exp()
        self.expect(")", expecting="')'")
        if not self.accept(":"):
            self.syntax_error(expecting="':'")
        sub = self.parse_pattern()
        return ("expr", e, sub, tok.loc)
    self.syntax_error()
Parser.parse_pattern_object_entry = _p_parse_pattern_object_entry

_KEY_NAME_TYPES = None

def _p_parse_object(self):
    otok = self.expect("{")
    entries = []
    if self.accept("}"):
        return self._finish(Node("object", entries, loc=otok.loc))
    while True:
        entries.append(self.parse_object_entry())
        if self.accept(","):
            if self.accept("}"):
                break
            continue
        if self.accept("}"):
            break
        self.syntax_error(expecting="'}'")
    return self._finish(Node("object", entries, loc=otok.loc))
Parser.parse_object = _p_parse_object

def _p_parse_object_entry(self):
    tok = self.peek()
    if tok.type == "BINDING":
        self.next()
        if self.accept(":"):
            val = self.parse_expd()
            return ("var", tok.value, val, tok.loc)
        vnode = Node("var", tok.value, loc=tok.loc)
        return ("var", tok.value, vnode, tok.loc)
    if tok.type == "LOC":
        self.next()
        if self.accept(":"):
            val = self.parse_expd()
            return ("name", "__loc__", val, tok.loc)
        vnode = Node("loc", loc=tok.loc)
        return ("name", "__loc__", vnode, tok.loc)
    if tok.type == "STRING_START" or tok.type == "FORMAT":
        strnode = self.parse_string_or_format()
        if self.accept(":"):
            val = self.parse_expd()
            return ("str", strnode, val, tok.loc)
        return ("str", strnode, None, tok.loc)
    if tok.type == "(":
        self.next()
        e = self.parse_exp()
        self.expect(")", expecting="')'")
        if not self.accept(":"):
            self.syntax_error(expecting="':'")
        val = self.parse_expd()
        return ("expr", e, val, tok.loc)
    if tok.type == "IDENT" or tok.type == "LITERALWORD" or tok.type in KEYWORDS:
        self.next()
        name = tok.value if tok.type in ("IDENT", "LITERALWORD") else tok.text
        if self.accept(":"):
            val = self.parse_expd()
            return ("name", name, val, tok.loc)
        return ("name", name, None, tok.loc)
    self.syntax_error()
Parser.parse_object_entry = _p_parse_object_entry

