_orig_parser_next = Parser.next
def _parser_next(self):
    t = _orig_parser_next(self)
    self._last_end = t.loc.end
    return t
Parser.next = _parser_next

def _finish(self, node):
    node.end = getattr(self, "_last_end", node.end)
    return node
Parser._finish = _finish

def _p_parse_string_literal(self, fmt=None):
    start_tok = self.expect("STRING_START", expecting="QQSTRING_START")
    parts = []
    while not self.at("STRING_END"):
        if self.at("EOF"):
            self.syntax_error(expecting="QQSTRING_TEXT or QQSTRING_INTERP_START or QQSTRING_END")
        if self.at("STRING_TEXT"):
            tok = self.next()
            try:
                s = decode_string_content_str(tok.text, allow_controls=True)
            except StringDecodeError as e:
                blen = len(tok.text.encode("utf-8", "surrogateescape"))
                msg = f"{e.msg} at line {tok.loc.line}, column {blen+2} (while parsing '\"{tok.text}\"')"
                err = CompileError(msg, tok.loc.source, tok.loc.line, tok.loc.col, blen)
                raise JqCompileException([err])
            if s:
                if parts and isinstance(parts[-1], str):
                    parts[-1] += s
                else:
                    parts.append(s)
        elif self.at("INTERP_START"):
            self.next()
            if self.at("INTERP_END"):
                self.syntax_error()
            expr = self.parse_exp()
            if not self.at("INTERP_END"):
                self.syntax_error(expecting="QQSTRING_INTERP_END or '|' or ','")
            self.next()
            parts.append(expr)
        else:
            self.syntax_error()
    self.next()
    node = Node("str", parts, fmt, loc=start_tok.loc)
    return self._finish(node)
Parser.parse_string_literal = _p_parse_string_literal

def _p_parse_string_or_format(self):
    if self.at("FORMAT"):
        ftok = self.next()
        if not self.at("STRING_START"):
            self.syntax_error(tok=ftok, expecting="QQSTRING_START")
        return self.parse_string_literal(fmt=ftok.value)
    return self.parse_string_literal(fmt=None)
Parser.parse_string_or_format = _p_parse_string_or_format

def _p_parse_program(self, is_library=False):
    prog = Program(self.source)
    prog.is_library = is_library
    if self.at("module"):
        mtok = self.next()
        meta_node = self.parse_postfix()
        self.expect(";", expecting="';'")
        prog.meta = self._eval_meta(meta_node)
    while self.at("import") or self.at("include"):
        prog.imports.append(self.parse_import())
    if is_library:
        while self.at("def"):
            prog.defs.append(self.parse_funcdef_raw())
        if not self.at("EOF"):
            # parse remaining as main (for syntax errors), then library error
            _e = self.parse_exp()
            self.expect("EOF", expecting="end of file")
            err = CompileError(None, raw="jq: error: jq: error: library should only have function definitions, not a main expression\n")
            raise JqCompileException([err])
        return prog
    if self.at("EOF"):
        raise JqCompileException([CompileError('Top-level program not given (try ".")')])
    prog.expr = self.parse_exp()
    if not self.at("EOF"):
        self.syntax_error(expecting="end of file")
    return prog
Parser.parse_program = _p_parse_program

def _p_eval_meta(self, node):
    # eval_constant_node defined later
    try:
        val = eval_constant_node(node)
    except NotConstant:
        caret = max(1, _span_len(self.source, node))
        err = CompileError("Module metadata must be constant", node.loc.source if node.loc else self.source, node.loc.line if node.loc else 1, node.loc.col if node.loc else 1, caret)
        raise JqCompileException([err])
    if not isinstance(val, dict):
        caret = max(1, _span_len(self.source, node))
        err = CompileError("Module metadata must be an object", node.loc.source if node.loc else self.source, node.loc.line if node.loc else 1, node.loc.col if node.loc else 1, caret)
        raise JqCompileException([err])
    return val
Parser._eval_meta = _p_eval_meta

def _span_len(source, node):
    if node.loc is None:
        return 1
    seg = source.text[node.loc.start:node.end]
    return len(seg.encode("utf-8", "surrogateescape"))

def _p_parse_import(self):
    kwtok = self.next()
    kind = kwtok.type
    if self.at("FORMAT") or self.at("STRING_START"):
        strnode = self.parse_string_or_format()
    else:
        self.syntax_error(expecting="FORMAT or QQSTRING_START")
    # constant path
    parts = strnode.x[0]
    if any(not isinstance(p, str) for p in parts):
        caret = max(1, _span_len(self.source, strnode))
        err = CompileError("Import path must be constant", strnode.loc.source, strnode.loc.line, strnode.loc.col, caret)
        raise JqCompileException([err])
    path = "".join(parts)
    alias = None; is_data = False
    if kind == "import":
        if not self.at("as"):
            self.syntax_error(expecting="as")
        self.next()
        if self.at("BINDING"):
            alias = self.next().value; is_data = True
        elif self.at("IDENT"):
            alias = self.next().value
        else:
            self.syntax_error(expecting="IDENT")
    meta = None
    if self.at("{") or self.at("("):
        meta_node = self.parse_postfix()
        meta = self._eval_meta(meta_node)
    self.expect(";", expecting="';'")
    return {"kind": kind, "path": path, "alias": alias, "is_data": is_data, "meta": meta, "loc": kwtok.loc}
Parser.parse_import = _p_parse_import

def _p_parse_params(self):
    params = []
    if self.accept("("):
        while True:
            if self.at("BINDING"):
                params.append((self.next().value, True))
            elif self.at("IDENT") or self.at("LITERALWORD"):
                params.append((self.next().value, False))
            else:
                self.syntax_error(expecting="IDENT or BINDING")
            if self.accept(";"):
                continue
            break
        self.expect(")", expecting="')'")
    return params

def _p_parse_funcdef_raw(self):
    dtok = self.expect("def")
    if self.at("IDENT") or self.at("LITERALWORD"):
        name = self.next().value
    else:
        self.syntax_error(expecting="IDENT")
    params = self._parse_params()
    if not self.at(":"):
        self.syntax_error(expecting="':' or '('")
    self.next()
    body = self.parse_exp()
    self.expect(";", expecting="';'")
    return self._finish(Node("funcdef", name, params, body, loc=dtok.loc))
Parser._parse_params = _p_parse_params
Parser.parse_funcdef_raw = _p_parse_funcdef_raw

def _p_parse_def_unit(self):
    dtok = self.expect("def")
    if self.at("IDENT") or self.at("LITERALWORD"):
        nametok = self.next(); name = nametok.value
    else:
        self.syntax_error(expecting="IDENT")
    params = self._parse_params()
    if not self.at(":"):
        self.syntax_error(expecting="':' or '('")
    self.next()
    body = self.parse_exp()
    self.expect(";", expecting="';'")
    rest = self.parse_exp()
    node = Node("def", name, params, body, rest, loc=nametok.loc)
    node.loc = nametok.loc
    return self._finish(node)
Parser.parse_def_unit = _p_parse_def_unit

def _p_parse_exp(self):
    left = self.parse_comma()
    if self.accept("|"):
        right = self.parse_exp()
        return self._finish(Node("pipe", left, right, loc=left.loc))
    return left
Parser.parse_exp = _p_parse_exp

def _p_parse_comma(self):
    first = self.parse_unit()
    if not self.at(","):
        return first
    items = [first]
    while self.accept(","):
        items.append(self.parse_unit())
    return self._finish(Node("comma", items, loc=first.loc))
Parser.parse_comma = _p_parse_comma

def _p_parse_unit(self):
    if self.at("def"):
        return self.parse_def_unit()
    if self.at("label"):
        ltok = self.next()
        if not self.at("BINDING"):
            self.syntax_error(expecting="BINDING")
        name = self.next().value
        if not self.accept("|"):
            self.syntax_error(expecting="'|'")
        body = self.parse_exp()
        return self._finish(Node("label", name, body, loc=ltok.loc))
    term = self.parse_alt()
    if self.at("as"):
        self.next()
        patterns = self.parse_patterns()
        if not self.accept("|"):
            self.syntax_error(expecting="'|'")
        body = self.parse_exp()
        return self._finish(Node("bind", term, patterns, body, loc=term.loc))
    return term
Parser.parse_unit = _p_parse_unit

def _p_parse_expd(self):
    left = self.parse_alt()
    if self.accept("|"):
        right = self.parse_expd()
        return self._finish(Node("pipe", left, right, loc=left.loc))
    return left
