_ASSIGN_OPS = {"=": ("assign", None), "|=": ("update", None), "+=": ("compound", "+"), "-=": ("compound", "-"), "*=": ("compound", "*"), "/=": ("compound", "/"), "%=": ("compound", "%"), "//=": ("compound", "//")}

def _p_parse_assign(self):
    left = self.parse_or()
    if self.peek().type in _ASSIGN_OPS:
        optok = self.next()
        rhs = self.parse_or()
        kind, op = _ASSIGN_OPS[optok.type]
        if self.peek().type in _ASSIGN_OPS:
            self.syntax_error()
        if kind == "assign":
            return self._finish(Node("assign", left, rhs, loc=left.loc))
        if kind == "update":
            return self._finish(Node("update", left, rhs, loc=left.loc))
        return self._finish(Node("compound", op, left, rhs, loc=left.loc))
