def _p_parse_bracket_suffix(self, allow_slice=True):
    self.expect("[")
    if self.accept("]"):
        return ("iter",)
    if self.at(":"):
        if not allow_slice:
            self.syntax_error(expecting="'|' or ',' or ']'")
        self.next()
        if self.at("]"):
            self.syntax_error()
        end = self.parse_exp()
        self.expect("]", expecting="']'")
        return ("slice", None, end)
    first = self.parse_exp()
    if self.at(":"):
        if not allow_slice:
            self.syntax_error(expecting="'|' or ',' or ']'")
        self.next()
        if self.at("]"):
            end = None
        else:
            end = self.parse_exp()
        self.expect("]", expecting="']'")
        return ("slice", first, end)
    self.expect("]", expecting="']'")
    return ("index", first)
