def _p_parse_primary_info(self):
    tok = self.peek()
    t = tok.type
    if t == "NUMBER":
        self.next()
        num = make_literal_number(tok.value)
        return (Node("lit", num, loc=tok.loc), False, [])
    if t == "LITERALWORD":
        self.next()
        v = {"true": True, "false": False, "null": None}[tok.value]
        return (Node("lit", v, loc=tok.loc), False, [])
    if t == "STRING_START":
        return (self.parse_string_literal(), False, [])
    if t == "FORMAT":
        ftok = self.next()
        if self.at("STRING_START"):
            return (self.parse_string_literal(fmt=ftok.value), False, [])
        return (Node("format", ftok.value, loc=ftok.loc), False, [])
    if t == "BINDING":
        self.next()
        return (Node("var", tok.value, loc=tok.loc), False, [])
    if t == "LOC":
        self.next()
        return (Node("loc", loc=tok.loc), False, [])
    if t == "FIELD":
        self.next()
        ident = Node("identity", loc=tok.loc)
        return (ident, False, [("field", tok.value)])
    if t == ".":
        self.next()
        return (Node("identity", loc=tok.loc), True, [])
    if t == "..":
        self.next()
        return (Node("call", "recurse", [], loc=tok.loc), False, [])
    if t == "(":
        self.next()
        if self.at(")"):
            self.syntax_error()
        e = self.parse_exp()
        self.expect(")", expecting="')'")
        return (e, False, [])
    if t == "[":
        ltok = self.next()
        if self.accept("]"):
            node = Node("array", None, loc=ltok.loc)
        else:
            e = self.parse_exp()
            self.expect("]", expecting="']'")
            node = Node("array", e, loc=ltok.loc)
        return (self._finish(node), False, [])
    if t == "{":
        return (self.parse_object(), False, [])
    if t == "IDENT":
        ntok = self.next()
        name = ntok.value
        args = []
        if self.at("("):
            self.next()
            args.append(self.parse_exp())
            while self.accept(";"):
                args.append(self.parse_exp())
            self.expect(")", expecting="')'")
        return (self._finish(Node("call", name, args, loc=ntok.loc)), False, [])
    if t == "if":
        return (self.parse_if(), False, [])
    if t == "try":
        return (self.parse_try(), False, [])
    if t in ("reduce", "foreach"):
        return (self.parse_reduce_for(), False, [])
    if t == "break":
        btok = self.next()
        if not self.at("BINDING"):
            self.syntax_error(expecting="BINDING")
        name = self.next().value
        # Note: break node covers 'break $name' for error location of undefined label
        node = Node("break", name, loc=btok.loc)
        return (self._finish(node), False, [])
    self.syntax_error()
Parser.parse_primary_info = _p_parse_primary_info

def _p_parse_if(self):
    itok = self.expect("if")
    branches = []
    cond = self.parse_exp()
    if not self.accept("then"):
        self.syntax_error(expecting="then or '|' or ','")
    branches.append((cond, self.parse_exp()))
    while self.at("elif"):
        self.next()
        c = self.parse_exp()
        if not self.accept("then"):
            self.syntax_error(expecting="then or '|' or ','")
        branches.append((c, self.parse_exp()))
    else_node = None
    if self.accept("else"):
        else_node = self.parse_exp()
    if not self.accept("end"):
        self.syntax_error(expecting="end")
    return self._finish(Node("if", branches, else_node, loc=itok.loc))
