def _p_parse_pattern_object_entry(self):
    tok = self.peek()
    if tok.type == "BINDING":
        self.next()
        if self.accept(":"):
            sub = self.parse_pattern()
            return ("var", tok.value, sub, tok.loc)
        return ("var", tok.value, ("var", tok.value, tok.loc), tok.loc)
    if tok.type in ("IDENT", "LITERALWORD") or tok.type in KEYWORDS:
        self.next()
        name = tok.value if tok.type != "IDENT" and tok.value else tok.text
        if tok.type == "IDENT" or tok.type == "LITERALWORD":
            name = tok.value
        else:
            name = tok.text
        if not self.accept(":"):
            self.syntax_error(expecting="':'")
        sub = self.parse_pattern()
        return ("name", name, sub, tok.loc)
    if tok.type == "STRING_START" or tok.type == "FORMAT":
        strnode = self.parse_string_or_format()
        if not self.accept(":"):
            self.syntax_error(expecting="':'")
        sub = self.parse_pattern()
        return ("str", strnode, sub, tok.loc)
    if tok.type == "(":
        self.next()
        e = self.parse_exp()
        self.expect(")", expecting="')'")
        if not self.accept(":"):
            self.syntax_error(expecting="':'")
        sub = self.parse_pattern()
        return ("expr", e, sub, tok.loc)
    self.syntax_error()
