def _p_parse_string_literal(self, fmt=None):
    start_tok = self.expect("STRING_START", expecting="QQSTRING_START")
    parts = []
    while not self.at("STRING_END"):
        if self.at("EOF"):
            self.syntax_error(expecting="QQSTRING_TEXT or QQSTRING_INTERP_START or QQSTRING_END")
        if self.at("STRING_TEXT"):
            tok = self.next()
            try:
                s = decode_string_content_str(tok.text, allow_controls=True)
            except StringDecodeError as e:
                blen = len(tok.text.encode("utf-8", "surrogateescape"))
                msg = f"{e.msg} at line {tok.loc.line}, column {blen+2} (while parsing '\"{tok.text}\"')"
                err = CompileError(msg, tok.loc.source, tok.loc.line, tok.loc.col, blen)
                raise JqCompileException([err])
            if s:
                if parts and isinstance(parts[-1], str):
                    parts[-1] += s
                else:
                    parts.append(s)
        elif self.at("INTERP_START"):
            self.next()
            if self.at("INTERP_END"):
                self.syntax_error()
            expr = self.parse_exp()
            if not self.at("INTERP_END"):
                self.syntax_error(expecting="QQSTRING_INTERP_END or '|' or ','")
            self.next()
            parts.append(expr)
        else:
            self.syntax_error()
    self.next()
    node = Node("str", parts, fmt, loc=start_tok.loc)
    return self._finish(node)
