def _p_parse_program(self, is_library=False):
    prog = Program(self.source)
    prog.is_library = is_library
    if self.at("module"):
        mtok = self.next()
        meta_node = self.parse_postfix()
        self.expect(";", expecting="';'")
        prog.meta = self._eval_meta(meta_node)
    while self.at("import") or self.at("include"):
        prog.imports.append(self.parse_import())
    if is_library:
        while self.at("def"):
            prog.defs.append(self.parse_funcdef_raw())
        if not self.at("EOF"):
            # parse remaining as main (for syntax errors), then library error
            _e = self.parse_exp()
            self.expect("EOF", expecting="end of file")
            err = CompileError(None, raw="jq: error: jq: error: library should only have function definitions, not a main expression\n")
            raise JqCompileException([err])
        return prog
    if self.at("EOF"):
        raise JqCompileException([CompileError('Top-level program not given (try ".")')])
    prog.expr = self.parse_exp()
    if not self.at("EOF"):
        self.syntax_error(expecting="end of file")
    return prog
