def _p_eval_meta(self, node):
    # eval_constant_node defined later
    try:
        val = eval_constant_node(node)
    except NotConstant:
        caret = max(1, _span_len(self.source, node))
        err = CompileError("Module metadata must be constant", node.loc.source if node.loc else self.source, node.loc.line if node.loc else 1, node.loc.col if node.loc else 1, caret)
        raise JqCompileException([err])
    if not isinstance(val, dict):
        caret = max(1, _span_len(self.source, node))
        err = CompileError("Module metadata must be an object", node.loc.source if node.loc else self.source, node.loc.line if node.loc else 1, node.loc.col if node.loc else 1, caret)
        raise JqCompileException([err])
    return val
