def _span_len(source, node):
    if node.loc is None:
        return 1
    seg = source.text[node.loc.start:node.end]
    return len(seg.encode("utf-8", "surrogateescape"))

def _p_parse_import(self):
    kwtok = self.next()
    kind = kwtok.type
    if self.at("FORMAT") or self.at("STRING_START"):
        strnode = self.parse_string_or_format()
    else:
        self.syntax_error(expecting="FORMAT or QQSTRING_START")
    # constant path
    parts = strnode.x[0]
    if any(not isinstance(p, str) for p in parts):
        caret = max(1, _span_len(self.source, strnode))
        err = CompileError("Import path must be constant", strnode.loc.source, strnode.loc.line, strnode.loc.col, caret)
        raise JqCompileException([err])
    path = "".join(parts)
    alias = None; is_data = False
    if kind == "import":
        if not self.at("as"):
            self.syntax_error(expecting="as")
        self.next()
        if self.at("BINDING"):
            alias = self.next().value; is_data = True
        elif self.at("IDENT"):
            alias = self.next().value
        else:
            self.syntax_error(expecting="IDENT")
    meta = None
    if self.at("{") or self.at("("):
        meta_node = self.parse_postfix()
        meta = self._eval_meta(meta_node)
    self.expect(";", expecting="';'")
    return {"kind": kind, "path": path, "alias": alias, "is_data": is_data, "meta": meta, "loc": kwtok.loc}
