            elif self.at("IDENT") or self.at("LITERALWORD"):
                params.append((self.next().value, False))
            else:
                self.syntax_error(expecting="IDENT or BINDING")
            if self.accept(";"):
                continue
            break
        self.expect(")", expecting="')'")
    return params

