def _p_parse_postfix(self):
    node, dot_identity, suffixes = self.parse_primary_info()
    current_base = node
    pending = list(suffixes)
    current = node
    def flush():
        nonlocal current, current_base, pending
        if pending:
            current = self._finish(Node("postfix", current_base, list(pending), loc=current_base.loc))
            pending = []
            current_base = current
        else:
            current = current_base
    first = True
    while True:
        if first and dot_identity and (self.at("STRING_START") or self.at("FORMAT")):
            # . "str" / .@fmt "str"
            if self.at("FORMAT") and self.peek(1).type != "STRING_START":
                break
            strnode = self.parse_string_or_format()
            pending.append(("index", strnode))
            dot_identity = False
            first = False
            continue
        first = False
        if self.at("FIELD"):
            pending.append(("field", self.next().value))
            continue
        if self.at("."):
            dtok = self.next()
            if self.at("STRING_START") or self.at("FORMAT"):
                if self.at("FORMAT") and self.peek(1).type != "STRING_START":
                    ft = self.peek()
                    self.syntax_error(tok=ft, expecting="QQSTRING_START")
                strnode = self.parse_string_or_format()
                pending.append(("index", strnode))
                continue
            if self.at("["):
                pending.append(self.parse_bracket_suffix(allow_slice=False))
                continue
            self.syntax_error(expecting="FORMAT or QQSTRING_START or '['")
        if self.at("["):
            pending.append(self.parse_bracket_suffix(allow_slice=True))
            continue
        if self.at("?"):
            self.next()
            flush()
            current = self._finish(Node("try", current, None, loc=current.loc))
            current_base = current
            continue
