        self.next()
        if self.at(")"):
            self.syntax_error()
        e = self.parse_exp()
        self.expect(")", expecting="')'")
        return (e, False, [])
    if t == "[":
        ltok = self.next()
        if self.accept("]"):
            node = Node("array", None, loc=ltok.loc)
        else:
            e = self.parse_exp()
            self.expect("]", expecting="']'")
