    if isinstance(a, JNum) and isinstance(b, JNum):
        return N(a.f * b.f)
    if isinstance(a, str) and isinstance(b, JNum):
        cnt = num_to_int(b)
        if cnt <= 0:
            return None
        return a * cnt
