        return jq_equal(a, b)
    if op == "!=":
        return not jq_equal(a, b)
    if op == "<":
        return jq_cmp(a, b) < 0
    if op == ">":
        return jq_cmp(a, b) > 0
    if op == "<=":
        return jq_cmp(a, b) <= 0
    if op == ">=":
        return jq_cmp(a, b) >= 0
