class NotConstant(Exception):
    pass

def eval_constant_node(node):
    # returns single constant value or raises NotConstant
    vals = _const_multi(node)
    if len(vals) != 1:
        raise NotConstant()
    return vals[0]

def _const_multi(node):
    k = node.kind
    if k == "lit":
        return [node.x[0]]
    if k == "str":
        parts, fmt = node.x
        if all(isinstance(p, str) for p in parts):
            return ["".join(parts)]
        raise NotConstant()
    if k == "comma":
        out = []
        for item in node.x[0]:
            out += _const_multi(item)
        return out
    if k == "array":
        e = node.x[0]
        if e is None:
            return [[]]
        return [_const_multi(e)]
    if k == "object":
        obj = {}
        for (kk, kd, val, _loc) in node.x[0]:
            if val is None:
                raise NotConstant()
            if kk == "name":
                key = kd
            elif kk == "str":
                key = eval_constant_node(kd)
                if not isinstance(key, str):
                    raise NotConstant()
            elif kk == "expr":
                key = eval_constant_node(kd)
                if not isinstance(key, str):
                    raise NotConstant()
            elif kk == "var":
                raise NotConstant()
            else:
                raise NotConstant()
            obj[key] = eval_constant_node(val)
        return [obj]
    if k == "binop":
        op, l, r = node.x
        if op in ("and", "or"):
            raise NotConstant()
        lv = eval_constant_node(l); rv = eval_constant_node(r)
        try:
            return [apply_binop(op, lv, rv)]
        except Exception:
            raise NotConstant()
    raise NotConstant()

