        return length if is_end else 0
    if not isinstance(val, JNum):
        err("Array/string slice indices must be integers")
    x = val.f
    if math.isnan(x):
        err("Array/string slice indices must be integers")
    if math.isinf(x):
        return length if (x > 0) == is_end else (0 if x < 0 else length) if False else (length if x > 0 else 0)
    if x < 0:
        x = x + length
    idx = math.ceil(x) if is_end else math.trunc(x)
    if idx < 0:
        idx = 0
    if idx > length:
        idx = length
    return idx

def slice_value(container, start, end):
    if container is None:
        return None
    if isinstance(container, (list, str)):
        L = len(container)
        s = slice_bound(start, L, False)
        e = slice_bound(end, L, True)
        if s < e:
            return container[s:e]
        return [] if isinstance(container, list) else ""
    err(cannot_index_msg(container, {}))

def index_value(container, key):
    if container is None:
        if isinstance(key, (str, JNum, dict)):
            return None
        err(cannot_index_msg(container, key))
    if isinstance(container, dict):
        if isinstance(key, str):
            return container.get(key, None)
        err(cannot_index_msg(container, key))
    if isinstance(container, list):
        if isinstance(key, JNum):
            idx = num_to_int(key)
            if idx < 0:
                idx += len(container)
            if 0 <= idx < len(container):
                return container[idx]
            return None
        if isinstance(key, dict):
            if "start" not in key or "end" not in key:
                err("Array/string slice indices must be integers")
            return slice_value(container, key.get("start"), key.get("end"))
        if isinstance(key, list):
            return []
        err(cannot_index_msg(container, key))
    if isinstance(container, str):
        if isinstance(key, dict):
            if "start" not in key or "end" not in key:
                err("Array/string slice indices must be integers")
            return slice_value(container, key.get("start"), key.get("end"))
        err(cannot_index_msg(container, key))
    err(cannot_index_msg(container, key))

def iterate_value(container):
    if isinstance(container, list):
        yield from container
        return
    if isinstance(container, dict):
        yield from container.values()
        return
    err(f"Cannot iterate over {value_desc(container)}")

def getpath_value(v, path):
    if not isinstance(path, list):
        err("Path must be specified as an array")
    cur = v
    for comp in path:
        cur = index_value(cur, comp)
    return cur

def _is_slice_comp(comp):
    return isinstance(comp, dict)

def setpath_value(v, path, newval):
    if not isinstance(path, list):
        err("Path must be specified as an array")
    def rec(cur, i):
        if i == len(path):
            return newval
        comp = path[i]
        last = (i == len(path) - 1)
        if isinstance(comp, dict):
            # slice
            if isinstance(cur, str):
                err("Cannot update string slices")
            if cur is None:
                cur = []
            if isinstance(cur, list):
                if "start" not in comp or "end" not in comp:
                    err("Array/string slice indices must be integers")
                L = len(cur)
                s = slice_bound(comp.get("start"), L, False)
                e = slice_bound(comp.get("end"), L, True)
                if last:
                    if not isinstance(newval, list):
                        err("A slice of an array can only be assigned another array")
                    return cur[:s] + list(newval) + cur[e:]
                sub = cur[s:e] if s < e else []
                newsub = rec(sub, i+1)
                if not isinstance(newsub, list):
                    err("A slice of an array can only be assigned another array")
                return cur[:s] + list(newsub) + cur[e:]
            err(cannot_index_msg(cur, comp))
        if isinstance(comp, str):
            if cur is None:
                cur = {}
            if isinstance(cur, dict):
                nxt = dict(cur)
                child = cur.get(comp, None)
                nxt[comp] = rec(child, i+1)
                return nxt
            err(cannot_index_msg(cur, comp))
        if isinstance(comp, JNum):
            idx = num_to_int(comp)
            if cur is None:
                cur = []
            if isinstance(cur, list):
                nxt = list(cur)
                if idx < 0:
                    idx2 = idx + len(nxt)
                    if idx2 < 0:
                        err("Out of bounds negative array index")
                    idx = idx2
                while len(nxt) <= idx:
                    nxt.append(None)
                nxt[idx] = rec(nxt[idx], i+1)
                return nxt
            err(cannot_index_msg(cur, comp))
        # other component types: trigger index error
        _ = index_value(cur, comp)
        err(cannot_index_msg(cur, comp))
    return rec(v, 0)

def _del_at(cur, path, i):
    if i == len(path):
        return None  # deleting root handled by caller
    comp = path[i]
    last = (i == len(path) - 1)
    if isinstance(comp, dict):
        if isinstance(cur, str):
            err("Cannot update string slices")
        if cur is None:
            return None
        if isinstance(cur, list):
            if "start" not in comp or "end" not in comp:
                err("Array/string slice indices must be integers")
            L = len(cur)
            s = slice_bound(comp.get("start"), L, False)
            e = slice_bound(comp.get("end"), L, True)
            if last:
                return cur[:s] + cur[e:]
            sub = cur[s:e] if s < e else []
            newsub = _del_at(sub, path, i+1)
            if not isinstance(newsub, list):
                newsub = []
            return cur[:s] + list(newsub) + cur[e:]
        err(cannot_index_msg(cur, comp))
    if cur is None:
        if isinstance(comp, (str, JNum)):
            return None
        err(cannot_index_msg(cur, comp))
    if isinstance(comp, str):
        if isinstance(cur, dict):
            if comp not in cur:
                return cur
            nxt = dict(cur)
            if last:
                del nxt[comp]
            else:
                nxt[comp] = _del_at(cur[comp], path, i+1)
            return nxt
        err(cannot_index_msg(cur, comp))
    if isinstance(comp, JNum):
        if isinstance(cur, list):
            idx = num_to_int(comp)
            if idx < 0:
                idx2 = idx + len(cur)
                if idx2 < 0:
                    err("Out of bounds negative array index")
                idx = idx2
            if idx >= len(cur):
                return cur
            nxt = list(cur)
            if last:
                del nxt[idx]
            else:
                nxt[idx] = _del_at(cur[idx], path, i+1)
            return nxt
        err(cannot_index_msg(cur, comp))
    _ = index_value(cur, comp)
    err(cannot_index_msg(cur, comp))

def delpaths_value(v, paths):
    if not isinstance(paths, list):
        err("Paths must be specified as an array")
    for p in paths:
        if not isinstance(p, list):
            err("Path must be specified as an array")
    if any(len(p) == 0 for p in paths):
        return None
    # sort descending by jq_cmp of path arrays
    from functools import cmp_to_key
    sorted_paths = sorted(paths, key=cmp_to_key(lambda a, b: jq_cmp(a, b)), reverse=True)
    result = v
    done = []
    for p in sorted_paths:
        # skip if an already-deleted path is a prefix of p (including equal)
        skip = False
        for d in done:
            if len(d) <= len(p) and all(jq_equal(d[k], p[k]) for k in range(len(d))):
                skip = True; break
        if skip:
            continue
        result = _del_at(result, p, 0)
        done.append(p)
    return result

def all_paths(v):
    # yields paths (excluding root) DFS
    if isinstance(v, list):
        for i, x in enumerate(v):
            p = [N(i)]
            yield p
            for sub in all_paths(x):
                yield p + sub
    elif isinstance(v, dict):
        for k, x in v.items():
            p = [k]
            yield p
            for sub in all_paths(x):
                yield p + sub

# ----- arithmetic -----
def arith_add(a, b):
    if a is None:
        return b
    if b is None:
        return a
    if isinstance(a, JNum) and isinstance(b, JNum):
        return N(a.f + b.f)
    if isinstance(a, str) and isinstance(b, str):
        return a + b
    if isinstance(a, list) and isinstance(b, list):
        return a + b
    if isinstance(a, dict) and isinstance(b, dict):
        r = dict(a)
        for k, val in b.items():
            r[k] = val
        return r
    err(f"{value_desc(a)} and {value_desc(b)} cannot be added")

def arith_sub(a, b):
    if isinstance(a, JNum) and isinstance(b, JNum):
        return N(a.f - b.f)
    if isinstance(a, list) and isinstance(b, list):
        return [x for x in a if not any(jq_equal(x, y) for y in b)]
    err(f"{value_desc(a)} and {value_desc(b)} cannot be subtracted")

def _deep_merge(a, b):
    r = dict(a)
    for k, val in b.items():
        if k in r and isinstance(r[k], dict) and isinstance(val, dict):
            r[k] = _deep_merge(r[k], val)
        else:
            r[k] = val
    return r

def arith_mul(a, b):
    if isinstance(a, JNum) and isinstance(b, JNum):
        return N(a.f * b.f)
    if isinstance(a, str) and isinstance(b, JNum):
        cnt = num_to_int(b)
        if cnt <= 0:
            return None
        return a * cnt
    if isinstance(a, JNum) and isinstance(b, str):
        cnt = num_to_int(a)
        if cnt <= 0:
            return None
        return b * cnt
    if isinstance(a, dict) and isinstance(b, dict):
        return _deep_merge(a, b)
    err(f"{value_desc(a)} and {value_desc(b)} cannot be multiplied")

def string_split_literal(s, sep):
    if sep == "":
        return list(s)
    return s.split(sep)

def arith_div(a, b):
    if isinstance(a, JNum) and isinstance(b, JNum):
        if b.f == 0.0:
            err(f"{value_desc(a)} and {value_desc(b)} cannot be divided because the divisor is zero")
        return N(a.f / b.f)
    if isinstance(a, str) and isinstance(b, str):
        return string_split_literal(a, b)
    err(f"{value_desc(a)} and {value_desc(b)} cannot be divided")

def arith_mod(a, b):
    if isinstance(a, JNum) and isinstance(b, JNum):
        ia = num_to_int(a); ib = num_to_int(b)
        if ib == 0:
            err(f"{value_desc(a)} and {value_desc(b)} cannot be divided (remainder) because the divisor is zero")
        # C remainder (sign of dividend)
        r = abs(ia) % abs(ib)
        if ia < 0:
            r = -r
        return N(r)
    err(f"{value_desc(a)} and {value_desc(b)} cannot be divided (remainder)")

def apply_binop(op, a, b):
    if op == "+":
        return arith_add(a, b)
    if op == "-":
        return arith_sub(a, b)
    if op == "*":
        return arith_mul(a, b)
    if op == "/":
        return arith_div(a, b)
    if op == "%":
        return arith_mod(a, b)
    if op == "==":
        return jq_equal(a, b)
    if op == "!=":
        return not jq_equal(a, b)
    if op == "<":
        return jq_cmp(a, b) < 0
    if op == ">":
        return jq_cmp(a, b) > 0
    if op == "<=":
        return jq_cmp(a, b) <= 0
    if op == ">=":
        return jq_cmp(a, b) >= 0
    raise AssertionError(op)

# ----- environment -----
class UFunc:
    __slots__ = ("kind", "name", "params", "body", "env", "arg_node", "arg_env", "value")
    def __init__(self, kind, name=None, params=None, body=None, env=None, arg_node=None, arg_env=None, value=None):
        self.kind = kind; self.name = name; self.params = params or []; self.body = body; self.env = env
        self.arg_node = arg_node; self.arg_env = arg_env; self.value = value

class Env:
    __slots__ = ("parent", "vars", "funcs")
    def __init__(self, parent=None, vars=None, funcs=None):
        self.parent = parent
        self.vars = vars or {}
        self.funcs = funcs or {}
    def child(self, vars=None, funcs=None):
        return Env(self, vars, funcs)
    def lookup_var(self, name):
        e = self
        while e is not None:
            if name in e.vars:
                return True, e.vars[name]
            e = e.parent
        return False, None
    def lookup_func(self, name, arity):
        e = self
        key = (name, arity)
        while e is not None:
            if key in e.funcs:
                return e.funcs[key]
            e = e.parent
        return None

def make_def_env(env, name, params, body):
    uf = UFunc("user", name=name, params=params, body=body, env=None)
    env2 = env.child(funcs={(name, len(params)): uf})
    uf.env = env2
    return env2, uf

class NotConstant(Exception):
    pass

def eval_constant_node(node):
    # returns single constant value or raises NotConstant
    vals = _const_multi(node)
    if len(vals) != 1:
        raise NotConstant()
    return vals[0]

def _const_multi(node):
    k = node.kind
    if k == "lit":
        return [node.x[0]]
    if k == "str":
        parts, fmt = node.x
        if all(isinstance(p, str) for p in parts):
            return ["".join(parts)]
        raise NotConstant()
    if k == "comma":
        out = []
        for item in node.x[0]:
            out += _const_multi(item)
        return out
    if k == "array":
        e = node.x[0]
        if e is None:
            return [[]]
        return [_const_multi(e)]
    if k == "object":
        obj = {}
        for (kk, kd, val, _loc) in node.x[0]:
            if val is None:
                raise NotConstant()
            if kk == "name":
                key = kd
            elif kk == "str":
                key = eval_constant_node(kd)
                if not isinstance(key, str):
                    raise NotConstant()
            elif kk == "expr":
                key = eval_constant_node(kd)
                if not isinstance(key, str):
                    raise NotConstant()
            elif kk == "var":
                raise NotConstant()
            else:
                raise NotConstant()
            obj[key] = eval_constant_node(val)
        return [obj]
    if k == "binop":
        op, l, r = node.x
        if op in ("and", "or"):
            raise NotConstant()
        lv = eval_constant_node(l); rv = eval_constant_node(r)
        try:
            return [apply_binop(op, lv, rv)]
        except Exception:
            raise NotConstant()
    raise NotConstant()

