class Ctx:
    def __init__(self):
        self.provider = None
        self.modules = {}  # relpath -> meta dict
        self.search_list = []
        self.jq_origin = "."
        self.prog_origin = "."
        self.dump_opts = DumpOpts(compact=True)
        self.loading_stack = []
        self.module_cache = {}
        self.global_env = None

# ----- pattern binding -----
def pattern_vars(pat):
    s = set()
    def rec(p):
        if p[0] == "var":
            s.add(p[1])
        elif p[0] == "array":
            for q in p[1]:
                rec(q)
        elif p[0] == "object":
            for (_kk, _kd, sub, _l) in p[1]:
                rec(sub)
    rec(pat)
    return s

def bind_pattern(pat, value, env, ctx):
    # yields dict of bindings
    kind = pat[0]
    if kind == "var":
        yield {pat[1]: value}
        return
    if kind == "array":
        pats = pat[1]
        def rec_arr(i, cur):
            if i == len(pats):
                yield cur; return
            subval = index_value(value, N(i))
            for d in bind_pattern(pats[i], subval, env, ctx):
                nxt = dict(cur); nxt.update(d)
                yield from rec_arr(i+1, nxt)
        yield from rec_arr(0, {})
        return
    if kind == "object":
        entries = pat[1]
        def rec_obj(i, cur):
            if i == len(entries):
                yield cur; return
            kk, kd, sub, _l = entries[i]
            if kk in ("var", "name"):
                keys = [kd]
            elif kk == "str":
                keys = eval_node(kd, value, env, ctx)
            elif kk == "expr":
                keys = eval_node(kd, value, env, ctx)
            else:
                keys = [kd]
            for key in keys:
                subval = index_value(value, key)
                for d in bind_pattern(sub, subval, env, ctx):
                    nxt = dict(cur); nxt.update(d)
                    yield from rec_obj(i+1, nxt)
        yield from rec_obj(0, {})
        return

def bind_alternatives(patterns, value, env, ctx):
    # yields Env
    allvars = set()
    for p in patterns:
        allvars |= pattern_vars(p)
    last = len(patterns) - 1
    for idx, pat in enumerate(patterns):
        try:
            lst = list(bind_pattern(pat, value, env, ctx))
        except JqError:
            if idx < last:
                continue
            raise
        for d in lst:
            full = {v: None for v in allvars}
            full.update(d)
            yield env.child(vars=full)
        return

# ----- evaluator -----
def eval_node(node, input_v, env, ctx):
    k = node.kind
    if k == "identity":
        yield input_v; return
    if k == "lit":
        yield node.x[0]; return
    if k == "str":
        yield from _eval_string(node, input_v, env, ctx); return
    if k == "format":
        yield apply_format(node.x[0], input_v, ctx); return
    if k == "var":
        found, v = env.lookup_var(node.x[0])
        if not found:
            err(f"${node.x[0]} is not defined")
        yield v; return
    if k == "loc":
        loc = node.loc
        yield {"file": loc.source.name, "line": N(loc.line)}; return
    if k == "comma":
        for item in node.x[0]:
            yield from eval_node(item, input_v, env, ctx)
        return
    if k == "pipe":
        left, right = node.x
        for v in eval_node(left, input_v, env, ctx):
            yield from eval_node(right, v, env, ctx)
        return
    if k == "alt":
        left, right = node.x
        found = False
        for v in eval_node(left, input_v, env, ctx):
            if v is not False and v is not None:
                found = True
                yield v
        if not found:
            yield from eval_node(right, input_v, env, ctx)
        return
    if k == "binop":
        yield from _eval_binop(node, input_v, env, ctx); return
    if k == "neg":
        for v in eval_node(node.x[0], input_v, env, ctx):
            if isinstance(v, JNum):
                yield v.neg()
            else:
                err(f"{value_desc(v)} cannot be negated")
        return
    if k == "postfix":
        yield from _eval_postfix(node, input_v, env, ctx); return
    if k == "call":
        yield from eval_call(node, input_v, env, ctx); return
    if k == "array":
        e = node.x[0]
        if e is None:
            yield []
        else:
            yield list(eval_node(e, input_v, env, ctx))
        return
    if k == "object":
        yield from _eval_object(node, input_v, env, ctx); return
    if k == "if":
        branches, else_node = node.x
        yield from _eval_if(branches, else_node, input_v, env, ctx); return
    if k == "try":
        body, catch = node.x
        try:
            yield from eval_node(body, input_v, env, ctx)
        except JqError as e:
            if catch is not None:
                yield from eval_node(catch, e.value, env, ctx)
        return
    if k == "def":
        name, params, body, rest = node.x
        env2, _uf = make_def_env(env, name, params, body)
        yield from eval_node(rest, input_v, env2, ctx)
        return
    if k == "bind":
        source, patterns, body = node.x
        for sv in eval_node(source, input_v, env, ctx):
            for env2 in bind_alternatives(patterns, sv, env, ctx):
                yield from eval_node(body, input_v, env2, ctx)
        return
    if k == "label":
        name, body = node.x
        try:
            yield from eval_node(body, input_v, env, ctx)
        except BreakLabel as b:
            if b.name != name:
                raise
        return
    if k == "break":
        raise BreakLabel(node.x[0])
    if k == "reduce":
        source, patterns, init, update = node.x
        yield from _eval_foreach(source, patterns, init, update, None, input_v, env, ctx, is_reduce=True); return
    if k == "foreach":
        source, patterns, init, update, extract = node.x
        yield from _eval_foreach(source, patterns, init, update, extract, input_v, env, ctx, is_reduce=False); return
    if k == "assign":
        lhs, rhs = node.x
        for rv in eval_node(rhs, input_v, env, ctx):
            result = input_v
            for p in eval_path(lhs, input_v, env, ctx):
                result = setpath_value(result, p, rv)
            yield result
        return
    if k == "update":
        lhs, upd = node.x
        yield _eval_update_assign(lhs, upd, input_v, env, ctx); return
    if k == "compound":
        op, lhs, rhs = node.x
        for rv in eval_node(rhs, input_v, env, ctx):
            result = input_v
            for p in eval_path(lhs, input_v, env, ctx):
                cur = getpath_value(result, p)
                if op == "//":
                    nv = cur if (cur is not False and cur is not None) else rv
                else:
                    nv = apply_binop(op, cur, rv)
                result = setpath_value(result, p, nv)
            yield result
        return
    err(f"internal: unknown node {k}")

def _eval_string(node, input_v, env, ctx):
    parts, fmt = node.x
    def rec(i, acc):
        if i == len(parts):
            yield acc; return
        p = parts[i]
        if isinstance(p, str):
            yield from rec(i+1, acc + p)
        else:
            for v in eval_node(p, input_v, env, ctx):
                if fmt is not None:
                    v = apply_format(fmt, v, ctx)
                yield from rec(i+1, acc + tostring_value(v))
    yield from rec(0, "")

def _eval_binop(node, input_v, env, ctx):
    op, left, right = node.x
    if op == "and":
        for a in eval_node(left, input_v, env, ctx):
            if truthy(a):
                for b in eval_node(right, input_v, env, ctx):
                    yield truthy(b)
            else:
                yield False
        return
    if op == "or":
        for a in eval_node(left, input_v, env, ctx):
            if truthy(a):
                yield True
            else:
                for b in eval_node(right, input_v, env, ctx):
                    yield truthy(b)
        return
    for a in eval_node(left, input_v, env, ctx):
        for b in eval_node(right, input_v, env, ctx):
            yield apply_binop(op, a, b)

def _eval_if(branches, else_node, input_v, env, ctx):
    # iterate branches: for each cond output
    def go(idx):
        if idx == len(branches):
            if else_node is None:
                yield input_v
            else:
                yield from eval_node(else_node, input_v, env, ctx)
            return
        cond, branch = branches[idx]
        for cv in eval_node(cond, input_v, env, ctx):
            if truthy(cv):
                yield from eval_node(branch, input_v, env, ctx)
            else:
                yield from go(idx+1)
    yield from go(0)

def _eval_foreach(source, patterns, init, update, extract, input_v, env, ctx, is_reduce):
    for init_state in eval_node(init, input_v, env, ctx):
        state = init_state
        for item in eval_node(source, input_v, env, ctx):
            for env2 in bind_alternatives(patterns, item, env, ctx):
                last = None; seen = False
                for u in eval_node(update, state, env2, ctx):
                    seen = True; last = u
                    if not is_reduce:
                        if extract is None:
                            yield u
                        else:
                            yield from eval_node(extract, u, env2, ctx)
                state = last if seen else None
        if is_reduce:
            yield state

def _eval_update_assign(lhs, upd, input_v, env, ctx):
    result = input_v
    deletions = []
    root_deleted = False
    for p in eval_path(lhs, input_v, env, ctx):
        cur = getpath_value(result, p)
        # first update output only
        it = eval_node(upd, cur, env, ctx)
        first_val = None; seen = False
        for v in it:
            first_val = v; seen = True; break
        # close iterator if generator
        try:
            it.close()
        except Exception:
            pass
        if not seen:
            if len(p) == 0:
                root_deleted = True
            deletions.append(p)
        else:
            result = setpath_value(result, p, first_val)
    if root_deleted:
        return None
    if deletions:
        result = delpaths_value(result, deletions)
    return result

def _eval_postfix(node, input_v, env, ctx):
    base, suffixes = node.x
    for bv in eval_node(base, input_v, env, ctx):
        yield from _apply_suffixes(bv, suffixes, 0, input_v, env, ctx)

def _apply_suffixes(val, suffixes, idx, orig_input, env, ctx):
    if idx == len(suffixes):
        yield val; return
    sfx = suffixes[idx]
    kind = sfx[0]
    if kind == "field":
        nv = index_value(val, sfx[1])
        yield from _apply_suffixes(nv, suffixes, idx+1, orig_input, env, ctx)
    elif kind == "index":
        for key in eval_node(sfx[1], orig_input, env, ctx):
            nv = index_value(val, key)
            yield from _apply_suffixes(nv, suffixes, idx+1, orig_input, env, ctx)
    elif kind == "iter":
        for item in iterate_value(val):
            yield from _apply_suffixes(item, suffixes, idx+1, orig_input, env, ctx)
    elif kind == "slice":
        _k, start_node, end_node = sfx
        starts = [None] if start_node is None else eval_node(start_node, orig_input, env, ctx)
        for sv in starts:
            ends = [None] if end_node is None else eval_node(end_node, orig_input, env, ctx)
            for ev in ends:
                nv = slice_value(val, sv, ev)
                yield from _apply_suffixes(nv, suffixes, idx+1, orig_input, env, ctx)

def _eval_object(node, input_v, env, ctx):
    entries = node.x[0]
    def rec(i, cur):
        if i == len(entries):
            yield cur; return
        kk, kd, valnode, _loc = entries[i]
        if kk == "name":
            key_iter = [kd]
        elif kk == "str":
            key_iter = eval_node(kd, input_v, env, ctx)
        elif kk == "var":
            key_iter = [kd]
        elif kk == "expr":
            key_iter = eval_node(kd, input_v, env, ctx)
        else:
            key_iter = [kd]
        for key in key_iter:
            if not isinstance(key, str):
                err(f"Cannot use {value_desc(key)} as object key")
            if valnode is None:
                value_iter = [index_value(input_v, key)]
            else:
                value_iter = eval_node(valnode, input_v, env, ctx)
            for v in value_iter:
                nxt = dict(cur); nxt[key] = v
                yield from rec(i+1, nxt)
    yield from rec(0, {})

def eval_call(node, input_v, env, ctx):
    name, args = node.x
    uf = env.lookup_func(name, len(args))
    if uf is not None:
        if uf.kind == "paramfilter":
            yield from eval_node(uf.arg_node, input_v, uf.arg_env, ctx)
            return
        if uf.kind == "const":
            yield uf.value
            return
        if uf.kind == "placeholder":
            # should not happen at runtime
            err(f"{name}/{len(args)} is not defined")
        # user
        yield from _call_user(uf, args, input_v, env, ctx)
        return
    yield from call_builtin(name, args, input_v, env, ctx, node)

def _call_user(uf, args, input_v, caller_env, ctx):
    params = uf.params
    # base call env is child of uf.env (definition env)
    def rec(i, call_env):
        if i == len(params):
            yield from eval_node(uf.body, input_v, call_env, ctx)
            return
        pname, is_value = params[i]
        anode = args[i]
        if is_value:
            for v in eval_node(anode, input_v, caller_env, ctx):
                const_uf = UFunc("const", value=v)
                env2 = call_env.child(vars={pname: v}, funcs={(pname, 0): const_uf})
                yield from rec(i+1, env2)
        else:
            pf = UFunc("paramfilter", arg_node=anode, arg_env=caller_env)
            env2 = call_env.child(funcs={(pname, 0): pf})
            yield from rec(i+1, env2)
    yield from rec(0, uf.env)

# ----- path evaluation -----
def eval_path(node, input_v, env, ctx):
    for (p, _v) in eval_path_pairs(node, input_v, env, ctx):
        yield p

def _is_path_capable(node, env, ctx):
    if node.kind in ("identity", "postfix", "pipe", "comma", "alt", "if", "try", "bind", "def", "label"):
        return True
    if node.kind == "call":
        name, args = node.x
        if env.lookup_func(name, len(args)) is not None:
            return True
        if (name, len(args)) in _PATH_SPECIAL_CALLS:
            return True
    return False

_PATH_SPECIAL_CALLS = set()

def eval_path_pairs(node, input_v, env, ctx):
    k = node.kind
    if k == "identity":
        yield ([], input_v); return
    if k == "postfix":
        yield from _eval_path_postfix(node, input_v, env, ctx); return
    if k == "pipe":
        left, right = node.x
        for (p, v) in eval_path_pairs(left, input_v, env, ctx):
            for (q, w) in eval_path_pairs(right, v, env, ctx):
                yield (p+q, w)
        return
    if k == "comma":
        for item in node.x[0]:
            yield from eval_path_pairs(item, input_v, env, ctx)
        return
    if k == "alt":
        left, right = node.x
        found = False
        for (p, v) in eval_path_pairs(left, input_v, env, ctx):
            if v is not False and v is not None:
                found = True
                yield (p, v)
        if not found:
            yield from eval_path_pairs(right, input_v, env, ctx)
        return
    if k == "if":
        branches, else_node = node.x
        def go(idx):
            if idx == len(branches):
                if else_node is None:
                    yield ([], input_v)
                else:
                    yield from eval_path_pairs(else_node, input_v, env, ctx)
                return
            cond, branch = branches[idx]
            for cv in eval_node(cond, input_v, env, ctx):
                if truthy(cv):
                    yield from eval_path_pairs(branch, input_v, env, ctx)
                else:
                    yield from go(idx+1)
        yield from go(0); return
    if k == "try":
        body, catch = node.x
        try:
            yield from eval_path_pairs(body, input_v, env, ctx)
        except JqError as e:
            if catch is not None:
                yield from eval_path_pairs(catch, e.value, env, ctx)
        return
    if k == "def":
        name, params, body, rest = node.x
        env2, _u = make_def_env(env, name, params, body)
        yield from eval_path_pairs(rest, input_v, env2, ctx); return
    if k == "bind":
        source, patterns, body = node.x
        for sv in eval_node(source, input_v, env, ctx):
            for env2 in bind_alternatives(patterns, sv, env, ctx):
                yield from eval_path_pairs(body, input_v, env2, ctx)
        return
    if k == "label":
        name, body = node.x
        try:
            yield from eval_path_pairs(body, input_v, env, ctx)
        except BreakLabel as b:
            if b.name != name:
                raise
        return
    if k == "break":
        raise BreakLabel(node.x[0])
    if k == "call":
        yield from _eval_path_call(node, input_v, env, ctx); return
    # fallback: invalid path with result
    for v in eval_node(node, input_v, env, ctx):
        err(f"Invalid path expression with result {short_dump(v)}")
    return

def _eval_path_postfix(node, input_v, env, ctx):
    base, suffixes = node.x
    if not _is_path_capable(base, env, ctx):
        # compute base normally and raise near-attempt error on first suffix
        for bv in eval_node(base, input_v, env, ctx):
            sfx = suffixes[0]
            if sfx[0] == "iter":
                err(f"Invalid path expression near attempt to iterate through {short_dump(bv)}")
            elif sfx[0] == "field":
                err(f"Invalid path expression near attempt to access element \"{sfx[1]}\" of {short_dump(bv)}")
            elif sfx[0] == "index":
                for key in eval_node(sfx[1], input_v, env, ctx):
                    err(f"Invalid path expression near attempt to access element {short_dump(key)} of {short_dump(bv)}")
                return
            elif sfx[0] == "slice":
                err(f"Invalid path expression near attempt to access element {short_dump(bv)}")
        return
    # states as generator of (path,value)
    def apply_all(states, idx):
        if idx == len(suffixes):
            yield from states
            return
        sfx = suffixes[idx]
        def gen():
            for (p, v) in states:
                if sfx[0] == "field":
                    nv = index_value(v, sfx[1])
                    yield (p+[sfx[1]], nv)
                elif sfx[0] == "index":
                    for key in eval_node(sfx[1], input_v, env, ctx):
                        nv = index_value(v, key)
                        yield (p+[key], nv)
                elif sfx[0] == "iter":
                    if isinstance(v, list):
                        for i, item in enumerate(v):
                            yield (p+[N(i)], item)
                    elif isinstance(v, dict):
                        for kk, item in v.items():
                            yield (p+[kk], item)
                    else:
                        err(f"Cannot iterate over {value_desc(v)}")
                elif sfx[0] == "slice":
                    _kk, sn, en = sfx
                    starts = [None] if sn is None else eval_node(sn, input_v, env, ctx)
                    for sv in starts:
                        ends = [None] if en is None else eval_node(en, input_v, env, ctx)
                        for ev in ends:
                            nv = slice_value(v, sv, ev)
                            comp = {"start": sv, "end": ev}
                            yield (p+[comp], nv)
        yield from apply_all(gen(), idx+1)
    yield from apply_all(eval_path_pairs(base, input_v, env, ctx), 0)

_SELECTORS = {
    "nulls": lambda v: v is None,
    "booleans": lambda v: isinstance(v, bool),
    "numbers": lambda v: isinstance(v, JNum),
    "strings": lambda v: isinstance(v, str),
    "arrays": lambda v: isinstance(v, list),
    "objects": lambda v: isinstance(v, dict),
    "iterables": lambda v: isinstance(v, (list, dict)),
    "scalars": lambda v: not isinstance(v, (list, dict)),
    "values": lambda v: v is not None,
    "normals": lambda v: isinstance(v, JNum) and math.isfinite(v.f) and v.f != 0 and not (0 < abs(v.f) < 2.2250738585072014e-308),
    "finites": lambda v: isinstance(v, JNum) and math.isfinite(v.f),
}

def _eval_path_call(node, input_v, env, ctx):
    name, args = node.x
    uf = env.lookup_func(name, len(args))
    if uf is not None:
        if uf.kind == "paramfilter":
            yield from eval_path_pairs(uf.arg_node, input_v, uf.arg_env, ctx); return
        if uf.kind == "const":
            err(f"Invalid path expression with result {short_dump(uf.value)}")
        if uf.kind == "user":
            yield from _call_user_path(uf, args, input_v, env, ctx); return
        err(f"Invalid path expression with result {short_dump(input_v)}")
    # special builtins
    arity = len(args)
    if name == "empty" and arity == 0:
        return
    if name == "recurse" and arity == 0:
        yield ([], input_v)
        # DFS
        def rec(p, v):
            if isinstance(v, list):
                for i, x in enumerate(v):
                    yield (p+[N(i)], x)
                    yield from rec(p+[N(i)], x)
            elif isinstance(v, dict):
                for kk, x in v.items():
                    yield (p+[kk], x)
                    yield from rec(p+[kk], x)
        yield from rec([], input_v); return
    if name == "select" and arity == 1:
        for cv in eval_node(args[0], input_v, env, ctx):
            if truthy(cv):
                yield ([], input_v); return
        return
    if name in _SELECTORS and arity == 0:
        if _SELECTORS[name](input_v):
            yield ([], input_v)
        return
    if name == "first" and arity == 1:
        for pair in eval_path_pairs(args[0], input_v, env, ctx):
            yield pair; return
        return
    if name == "limit" and arity == 2:
        for nv in eval_node(args[0], input_v, env, ctx):
            if not isinstance(nv, JNum):
                err(f"{value_desc(nv)} limit count must be a number" if False else "limit count must be a number")
            cnt = num_to_int(nv)
            if cnt < 0:
                err("limit count must be a number" if False else f"limit count must be a number")
            n = 0
            for pair in eval_path_pairs(args[1], input_v, env, ctx):
                if n >= cnt:
                    break
                yield pair; n += 1
        return
    if name == "nth" and arity == 2:
        for nv in eval_node(args[0], input_v, env, ctx):
            cnt = num_to_int(nv) if isinstance(nv, JNum) else 0
            for i, pair in enumerate(eval_path_pairs(args[1], input_v, env, ctx)):
                if i == cnt:
                    yield pair; break
        return
    if name == "skip" and arity == 2:
        for nv in eval_node(args[0], input_v, env, ctx):
            cnt = num_to_int(nv) if isinstance(nv, JNum) else 0
            for i, pair in enumerate(eval_path_pairs(args[1], input_v, env, ctx)):
                if i >= cnt:
                    yield pair
        return
    # fallback normal
    for v in eval_node(node, input_v, env, ctx):
        err(f"Invalid path expression with result {short_dump(v)}")
    return

# register path-special call names for _is_path_capable
for _nm, _ar in [("empty",0),("recurse",0),("select",1),("first",1),("limit",2),("nth",2),("skip",2)] + [(k,0) for k in _SELECTORS]:
    _PATH_SPECIAL_CALLS.add((_nm,_ar))

def _call_user_path(uf, args, input_v, caller_env, ctx):
    params = uf.params
    def rec(i, call_env):
        if i == len(params):
            yield from eval_path_pairs(uf.body, input_v, call_env, ctx); return
        pname, is_value = params[i]
        anode = args[i]
        if is_value:
            for v in eval_node(anode, input_v, caller_env, ctx):
                env2 = call_env.child(vars={pname: v}, funcs={(pname,0): UFunc("const", value=v)})
                yield from rec(i+1, env2)
        else:
            env2 = call_env.child(funcs={(pname,0): UFunc("paramfilter", arg_node=anode, arg_env=caller_env)})
            yield from rec(i+1, env2)
    yield from rec(0, uf.env)

