import ctypes as _ctypes_mod
_cdouble = _ctypes_mod.c_double
_cint = _ctypes_mod.c_int
_clong = _ctypes_mod.c_long

_MATH1 = {}
_MATH2 = {}
_MATH3 = {}
if _libm is not None:
    for _nm in ["acos","acosh","asin","asinh","atan","atanh","cbrt","ceil","cosh","cos","erf","erfc","exp","exp10","exp2","expm1","fabs","floor","j0","j1","lgamma","log","log10","log1p","log2","logb","nearbyint","rint","round","significand","sin","sinh","sqrt","tan","tanh","tgamma","trunc","y0","y1","gamma"]:
        _f = _libm_func(_nm, [_cdouble], _cdouble)
        if _f:
            _MATH1[_nm] = _f
    # binary: name -> (func, kind) kind: dd, di (int,double?) etc handled specially
    for _nm in ["atan2","copysign","drem","fdim","fmax","fmin","fmod","hypot","pow","remainder","scalb","nextafter"]:
        _f = _libm_func(_nm, [_cdouble, _cdouble], _cdouble)
        if _f:
            _MATH2[_nm] = _f
    _f = _libm_func("fma", [_cdouble, _cdouble, _cdouble], _cdouble)
    if _f:
        _MATH3["fma"] = _f

def _math1_py(name, x):
    try:
        if name == "fabs": return math.fabs(x)
        if name == "gamma": return math.lgamma(x)
        if name == "exp10": return 10.0 ** x
        if name == "significand":
            if x == 0: return 0.0
            m, e = math.frexp(x); return m * 2.0
        if name == "logb":
            if x == 0: return -math.inf
            m, e = math.frexp(abs(x)); return float(e - 1)
        if name == "j0" or name == "j1" or name == "y0" or name == "y1":
            return math.nan
        fn = getattr(math, name, None)
        if fn:
            return float(fn(x))
    except OverflowError:
        return math.inf
    except ValueError:
        # domain: distinguish -inf for log(0) etc
        if name in ("log", "log10", "log2", "log1p") and x == 0:
            return -math.inf
        return math.nan
    except Exception:
        return math.nan
    return math.nan

def call_math1(name, x):
    if name in _MATH1:
        return float(_MATH1[name](x))
    return _math1_py(name, x)

def call_math2(name, a, b):
    # a,b floats (for int-first functions, a is int value as float)
    if _libm is not None:
        try:
            if name in ("jn", "yn"):
                f = _libm_func(name, [_cint, _cdouble], _cdouble)
                if f: return float(f(int(a), b))
            if name == "ldexp":
                f = _libm_func("ldexp", [_cdouble, _cint], _cdouble)
                if f: return float(f(a, int(b)))
            if name == "scalbln":
                f = _libm_func("scalbln", [_cdouble, _clong], _cdouble)
                if f: return float(f(a, int(b)))
            if name == "nexttoward":
                f = getattr(_libm, "nexttoward")
                f.argtypes = [_cdouble, _ctypes_mod.c_longdouble]; f.restype = _cdouble
                return float(f(a, b))
            if name in _MATH2:
                return float(_MATH2[name](a, b))
        except Exception:
            pass
    # python fallbacks
    try:
        if name == "atan2": return math.atan2(a, b)
        if name == "copysign": return math.copysign(a, b)
        if name == "fmax": return a if a >= b else b
        if name == "fmin": return a if a <= b else b
        if name == "fmod" or name == "drem" or name == "remainder":
            if name == "fmod": return math.fmod(a, b)
            return math.remainder(a, b)
        if name == "hypot": return math.hypot(a, b)
        if name == "pow": return math.pow(a, b)
        if name == "ldexp": return math.ldexp(a, int(b))
        if name == "nextafter" or name == "nexttoward": return math.nextafter(a, b)
        if name == "scalb" or name == "scalbln": return a * (2.0 ** b)
        if name == "fdim": return a - b if a > b else 0.0
    except OverflowError:
        return math.inf
    except ValueError:
        return math.nan
    except Exception:
        return math.nan
    return math.nan

# ---- dates ----
def _broken_down_to_list(tm, frac_sec_extra=0.0):
    # tm is time.struct_time
    sec = float(tm.tm_sec) + frac_sec_extra
    return [N(tm.tm_year), N(tm.tm_mon - 1), N(tm.tm_mday), N(tm.tm_hour), N(tm.tm_min), N(sec) if frac_sec_extra else N(tm.tm_sec), N(tm.tm_wday), N(tm.tm_yday)]

def _timestamp_to_broken(v, use_local=False):
    if isinstance(v, list):
        # validate (?) use fields as given for strftime; return struct_time-like tuple
        return v
    if not isinstance(v, JNum):
        err(f"{value_desc(v)} is not a number or array" if False else f"{type_name(v)} ({short_dump(v)}) cannot be formatted as a date")
    f = v.f
    frac = f - math.floor(f)
    secs = int(math.floor(f)) if math.isfinite(f) else 0
    try:
        tm = time.localtime(secs) if use_local else time.gmtime(secs)
    except Exception:
        err(f"{value_desc(v)} is outside the range of representable dates" if False else "date out of range")
    lst = _broken_down_to_list(tm, frac if frac else 0.0)
    return lst

def _list_to_struct_time(arr):
    # arr: [year, mon0, mday, hour, min, sec, wday, yday]
    def gi(i, default=0):
        if i < len(arr) and isinstance(arr[i], JNum):
            return num_to_int(arr[i])
        return default
    year = gi(0, 1970); mon = gi(1, 0) + 1; mday = gi(2, 1); hour = gi(3); minute = gi(4)
    sec_val = arr[5].f if len(arr) > 5 and isinstance(arr[5], JNum) else 0.0
    sec = int(sec_val)
    # compute wday/yday via datetime if possible (for strftime %j etc), else use given
    wday = gi(6, 0); yday = gi(7, 0)
    # struct_time expects tm_wday Monday=0; jq wday Sunday=0. Convert: python wday Mon0 = (jq_wday+6)%7
    py_wday = (wday + 6) % 7
    return time.struct_time((year, mon, mday, hour, minute, sec, py_wday, yday + 1, -1))

def _format_date(input_v, fmt, use_local, fname):
    # fname for errors
    if not isinstance(fmt, str):
        err(f"{fname}/1 requires a string format")
    if isinstance(input_v, list):
        try:
            st = _list_to_struct_time(input_v)
        except Exception:
            err("invalid date array")
        try:
            return time.strftime(fmt, st)
        except Exception as e:
            err(str(e))
    if not isinstance(input_v, JNum):
        # jq: strftime on non-number/array?
        err(f"{value_desc(input_v)} cannot be formatted as a date" if False else f"{fname} requires a number or array input")
    f = input_v.f
    secs = int(math.floor(f)) if math.isfinite(f) else 0
    try:
        tm = time.localtime(secs) if use_local else time.gmtime(secs)
    except Exception:
        err("date out of range")
    return time.strftime(fmt, tm)

