# ---------------- format / regex / date / math helpers ----------------
def apply_format(fmt, v, ctx=None):
    if fmt == "text":
        return tostring_value(v)
    if fmt == "json":
        return tojson_compact(v)
    if fmt == "html":
        s = tostring_value(v)
        return (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("'", "&apos;").replace('"', "&quot;"))
    if fmt == "uri":
        s = tostring_value(v)
        out = []
        for b in s.encode("utf-8"):
            ch = chr(b)
            if ch.isalnum() and b < 128 or ch in "-_.~":
                out.append(ch)
            else:
                out.append("%%%02X" % b)
        return "".join(out)
    if fmt == "csv":
        if not isinstance(v, list):
            err(f"{value_desc(v)} cannot be csv-formatted, only array")
        cells = []
        for x in v:
            if x is None:
                cells.append("")
            elif isinstance(x, bool):
                cells.append("true" if x else "false")
            elif isinstance(x, JNum):
                cells.append(number_to_string(x))
            elif isinstance(x, str):
                cells.append('"' + x.replace('"', '""') + '"')
            else:
                err(f"{value_desc(x)} is not valid in a csv row")
        return ",".join(cells)
    if fmt == "tsv":
        if not isinstance(v, list):
            err(f"{value_desc(v)} cannot be tsv-formatted, only array")
        cells = []
        for x in v:
            if x is None:
                cells.append("")
            elif isinstance(x, bool):
                cells.append("true" if x else "false")
            elif isinstance(x, JNum):
                cells.append(number_to_string(x))
            elif isinstance(x, str):
                cells.append(x.replace("\\", "\\\\").replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t"))
            else:
                err(f"{value_desc(x)} is not valid in a tsv row")
        return "\t".join(cells)
    if fmt == "sh":
        if isinstance(v, str):
            return "'" + v.replace("'", "'\\''") + "'"
        if v is None or isinstance(v, (bool, JNum)):
            return tostring_value(v)
        if isinstance(v, list):
            parts = []
            for x in v:
                if isinstance(x, str):
                    parts.append("'" + x.replace("'", "'\\''") + "'")
                elif x is None or isinstance(x, (bool, JNum)):
                    parts.append(tostring_value(x))
                else:
                    err(f"{value_desc(x)} can not be escaped for shell")
            return " ".join(parts)
        err(f"{value_desc(v)} can not be escaped for shell")
    if fmt == "base64":
        return base64.b64encode(tostring_value(v).encode("utf-8")).decode("ascii")
    if fmt == "base64d":
        s = tostring_value(v)
        return _base64_decode(s)
    err(f"{fmt} is not a valid format")

_B64_ALPHABET = {c: i for i, c in enumerate("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/")}

def _base64_decode(s):
    out = bytearray()
    acc = 0; cnt = 0
    terminated = False
    for ch in s:
        if ch == "=":
            terminated = True
            break
        if ch not in _B64_ALPHABET:
            err(f"string ({short_dump(s)}) is not valid base64 data")
        acc = (acc << 6) | _B64_ALPHABET[ch]
        cnt += 1
        if cnt == 4:
            out += bytes([(acc >> 16) & 0xFF, (acc >> 8) & 0xFF, acc & 0xFF])
            acc = 0; cnt = 0
    if cnt == 1:
        err(f"string ({short_dump(s)}) trailing base64 byte found")
    if cnt == 2:
        out.append((acc >> 4) & 0xFF)
    elif cnt == 3:
        out.append((acc >> 10) & 0xFF); out.append((acc >> 2) & 0xFF)
    return sanitize_utf8_bytes(bytes(out))

