class _OnigRegion(ctypes.Structure if _onig else object):
    _fields_ = [("allocated", ctypes.c_int), ("num_regs", ctypes.c_int), ("beg", ctypes.POINTER(ctypes.c_int)), ("end", ctypes.POINTER(ctypes.c_int)), ("history_root", ctypes.c_void_p)] if _onig else []

class _OnigErrorInfo(ctypes.Structure if _onig else object):
    _fields_ = [("enc", ctypes.c_void_p), ("par", ctypes.c_void_p), ("par_end", ctypes.c_void_p)] if _onig else []

_onig_funcs_ready = False
_onig_enc_addr = None
_onig_syntax_addr = None

def _init_onig():
    global _onig_funcs_ready, _onig_enc_addr, _onig_syntax_addr
    if _onig_funcs_ready or _onig is None:
        return _onig is not None
    try:
        class _Blob(ctypes.Structure):
            _fields_ = [("b", ctypes.c_char)]
        enc_blob = _Blob.in_dll(_onig, "OnigEncodingUTF8")
        syn_blob = _Blob.in_dll(_onig, "OnigSyntaxOniguruma")
        _onig_enc_addr = ctypes.addressof(enc_blob)
        _onig_syntax_addr = ctypes.addressof(syn_blob)
        _onig.onig_new.argtypes = [ctypes.POINTER(ctypes.c_void_p), ctypes.c_void_p, ctypes.c_void_p, ctypes.c_uint, ctypes.c_void_p, ctypes.c_void_p, ctypes.POINTER(_OnigErrorInfo)]
        _onig.onig_new.restype = ctypes.c_int
        _onig.onig_search.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p, ctypes.POINTER(_OnigRegion), ctypes.c_uint]
        _onig.onig_search.restype = ctypes.c_int
        _onig.onig_region_new.argtypes = []; _onig.onig_region_new.restype = ctypes.POINTER(_OnigRegion)
        _onig.onig_region_free.argtypes = [ctypes.POINTER(_OnigRegion), ctypes.c_int]; _onig.onig_region_free.restype = None
        _onig.onig_free.argtypes = [ctypes.c_void_p]; _onig.onig_free.restype = None
        _onig.onig_number_of_captures.argtypes = [ctypes.c_void_p]; _onig.onig_number_of_captures.restype = ctypes.c_int
        _onig.onig_error_code_to_str.restype = ctypes.c_int
        _onig_funcs_ready = True
        return True
    except Exception:
        return False

_ONIG_OPT_IGNORECASE = 1
_ONIG_OPT_EXTEND = 2
_ONIG_OPT_MULTILINE = 4
_ONIG_OPT_SINGLELINE = 8
_ONIG_OPT_FIND_LONGEST = 16
_ONIG_OPT_FIND_NOT_EMPTY = 32

def _parse_regex_flags(flags):
    global_flag = False
    opts = 0
    for ch in flags:
        if ch == "g":
            global_flag = True
        elif ch == "i":
            opts |= _ONIG_OPT_IGNORECASE
        elif ch == "x":
            opts |= _ONIG_OPT_EXTEND
        elif ch == "m":
            opts |= _ONIG_OPT_MULTILINE
        elif ch == "s":
            opts |= _ONIG_OPT_SINGLELINE
        elif ch == "p":
            opts |= _ONIG_OPT_MULTILINE | _ONIG_OPT_SINGLELINE
        elif ch == "l":
            opts |= _ONIG_OPT_FIND_LONGEST
        elif ch == "n":
            opts |= _ONIG_OPT_FIND_NOT_EMPTY
        else:
            err(f"{flags} is not a valid modifier string")
    return global_flag, opts

class RegexMatchInfo:
    __slots__ = ("beg_b", "end_b", "groups", "names")
    def __init__(self, beg_b, end_b, groups, names):
        self.beg_b = beg_b; self.end_b = end_b; self.groups = groups; self.names = names  # groups: list of (beg_b,end_b) per capture (1-based semantics in list order)

class RegexEngine:
    def __init__(self, pattern: str, flags: str):
        self.pattern = pattern
        self.flags = flags
        self.is_global, self.opts = _parse_regex_flags(flags)
        self._onig_reg = None
        self._names = {}  # group num -> name
        self._num_caps = 0
        self._use_onig = _init_onig()
        self._py_re = None
        if self._use_onig:
            self._compile_onig()
        else:
            self._compile_python()
    def _compile_onig(self):
        pat = self.pattern.encode("utf-8")
        pat_buf = ctypes.create_string_buffer(pat, len(pat))
        reg = ctypes.c_void_p()
        einfo = _OnigErrorInfo()
        r = _onig.onig_new(ctypes.byref(reg), ctypes.addressof(pat_buf), ctypes.addressof(pat_buf) + len(pat), self.opts, _onig_enc_addr, _onig_syntax_addr, ctypes.byref(einfo))
        if r != 0:
            buf = ctypes.create_string_buffer(1024)
            try:
                _onig.onig_error_code_to_str(buf, r, ctypes.byref(einfo))
                msg = buf.value.decode("utf-8", "replace")
            except Exception:
                msg = "unknown error"
            err(f"Regex failure: {msg}")
        self._onig_reg = reg
        self._num_caps = _onig.onig_number_of_captures(reg)
        # named groups
        try:
            CB = ctypes.CFUNCTYPE(ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p, ctypes.c_int, ctypes.POINTER(ctypes.c_int), ctypes.c_void_p, ctypes.c_void_p)
            names = {}
            def _cb(name_ptr, name_end, num, nums, _reg, _arg):
                ln = name_end - name_ptr
                nm = ctypes.string_at(name_ptr, ln).decode("utf-8", "replace")
                for ii in range(num):
                    names[nums[ii]] = nm
                return 0
            cb = CB(_cb)
            _onig.onig_foreach_name.argtypes = [ctypes.c_void_p, CB, ctypes.c_void_p]
            _onig.onig_foreach_name.restype = ctypes.c_int
            _onig.onig_foreach_name(reg, cb, None)
            self._names = names
        except Exception:
            self._names = {}
    def _compile_python(self):
        # Minimal translation fallback
        pat = self.pattern
        pat = re.sub(r"\(\?<([A-Za-z_][A-Za-z0-9_]*)>", r"(?P<\1>", pat)
        pat = pat.replace("[[:alpha:]]", "[A-Za-z]").replace("[[:digit:]]", "[0-9]").replace("[[:alnum:]]", "[A-Za-z0-9]").replace("[[:space:]]", r"\s")
        flags = 0
        if self.opts & _ONIG_OPT_IGNORECASE:
            flags |= re.IGNORECASE
        if self.opts & _ONIG_OPT_MULTILINE:
            flags |= re.DOTALL
        if self.opts & _ONIG_OPT_EXTEND:
            flags |= re.VERBOSE
        try:
            self._py_re = re.compile(pat, flags)
        except re.error as e:
            err(f"Regex failure: {e}")
        self._num_caps = self._py_re.groups
        self._names = {v: k for k, v in self._py_re.groupindex.items()}
    def __del__(self):
        try:
            if self._onig_reg:
                _onig.onig_free(self._onig_reg)
                self._onig_reg = None
        except Exception:
            pass
    def search_from(self, s_bytes: bytes, pos_b: int):
        if self._use_onig:
            region = _onig.onig_region_new()
            buf = ctypes.create_string_buffer(s_bytes, len(s_bytes))
            base = ctypes.addressof(buf)
            r = _onig.onig_search(self._onig_reg, base, base + len(s_bytes), base + pos_b, base + len(s_bytes), region, 0)
            if r == -1:  # mismatch
                _onig.onig_region_free(region, 1)
                return None
            if r < 0:
                cbuf = ctypes.create_string_buffer(1024)
                try:
                    _onig.onig_error_code_to_str(cbuf, r)
                    msg = cbuf.value.decode("utf-8", "replace")
                except Exception:
                    msg = "unknown error"
                _onig.onig_region_free(region, 1)
                err(f"Regex failure: {msg}")
            reg = region.contents
            groups = []
            # num_regs includes group 0
            nreg = reg.num_regs
            for gi in range(1, nreg):
                groups.append((reg.beg[gi], reg.end[gi]))
            # pad to num captures if region smaller
            while len(groups) < self._num_caps:
                groups.append((-1, -1))
            beg = reg.beg[0]; end = reg.end[0]
            _onig.onig_region_free(region, 1)
            return RegexMatchInfo(beg, end, groups, self._names)
        else:
            s = s_bytes.decode("utf-8", "replace")
            # pos_b is byte offset; convert to char index
            cpos = len(s_bytes[:pos_b].decode("utf-8", "ignore"))
            m = self._py_re.search(s, cpos)
            if not m:
                return None
            def bidx(cidx):
                return len(s[:cidx].encode("utf-8")) if cidx >= 0 else -1
            groups = []
            for gi in range(1, self._num_caps+1):
                if m.start(gi) == -1:
                    groups.append((-1, -1))
                else:
                    groups.append((bidx(m.start(gi)), bidx(m.end(gi))))
            return RegexMatchInfo(bidx(m.start()), bidx(m.end()), groups, self._names)

def _byte_to_char_idx(s: str, bpos: int):
    if bpos < 0:
        return -1
    # count codepoints in utf-8 encoding up to bpos
    enc = s.encode("utf-8")
    return len(enc[:bpos].decode("utf-8", "ignore"))

def regex_all_matches(engine: RegexEngine, s: str):
    sb = s.encode("utf-8")
    pos = 0
    L = len(sb)
    while pos <= L:
        m = engine.search_from(sb, pos)
        if m is None:
            break
        yield m
        if m.end_b == m.beg_b:
            if m.beg_b >= L:
                break
            # advance one codepoint
            # find next utf8 boundary
            nb = m.beg_b + 1
            while nb < L and (sb[nb] & 0xC0) == 0x80:
                nb += 1
            pos = nb
        else:
            pos = m.end_b

def match_object(engine: RegexEngine, s: str, m: RegexMatchInfo):
    beg_c = _byte_to_char_idx(s, m.beg_b)
    end_c = _byte_to_char_idx(s, m.end_b)
    caps = []
    for gi, (gb, ge) in enumerate(m.groups, start=1):
        name = m.names.get(gi)
        if gb < 0:
            caps.append({"offset": N(-1), "string": None, "length": N(0), "name": name})
        else:
            gbc = _byte_to_char_idx(s, gb); gec = _byte_to_char_idx(s, ge)
            caps.append({"offset": N(gbc), "length": N(gec-gbc), "string": s[gbc:gec], "name": name})
    return {"offset": N(beg_c), "length": N(end_c-beg_c), "string": s[beg_c:end_c], "captures": caps}

def capture_object(engine: RegexEngine, s: str, m: RegexMatchInfo):
    obj = {}
    for gi, (gb, ge) in enumerate(m.groups, start=1):
        name = m.names.get(gi)
        if name is None:
            continue
        if gb < 0:
            # only set if not already present with a value? jq: later groups overwrite? test showed {"x":"b"} where first x unmatched, second matched -> so skip/null then overwrite works if we set null first then b
            if name not in obj:
                obj[name] = None
            # if a previous value exists, keep? For (a)|(?<x>b) case first matched sets, second unmatched should not overwrite with null. Use: only set null if absent
        else:
            gbc = _byte_to_char_idx(s, gb); gec = _byte_to_char_idx(s, ge)
            obj[name] = s[gbc:gec]
    return obj

def get_regex_arg(regex_val, flags_val_present=False, flags_val=None):
    """Returns (pattern, flags_str). Handles string or array regex forms."""
    flags = ""
    pattern = None
    if isinstance(regex_val, str):
        pattern = regex_val
    elif isinstance(regex_val, list):
        if len(regex_val) == 0:
            err("array not a string or array")
        if not isinstance(regex_val[0], str):
            err(f"{value_desc(regex_val[0])} is not a string")
        pattern = regex_val[0]
        if len(regex_val) >= 2:
            if not isinstance(regex_val[1], str):
                err(f"{value_desc(regex_val[1])} is not a string")
            flags = regex_val[1]
    else:
        # error wording: "number not a string or array" (type only, no desc)
