def _libm_func(name, argtypes, restype):
    if _libm is None:
        return None
    try:
        f = getattr(_libm, name)
        f.argtypes = argtypes; f.restype = restype
        return f
    except Exception:
        return None

import ctypes as _ctypes_mod
_cdouble = _ctypes_mod.c_double
_cint = _ctypes_mod.c_int
_clong = _ctypes_mod.c_long

_MATH1 = {}
_MATH2 = {}
_MATH3 = {}
if _libm is not None:
    for _nm in ["acos","acosh","asin","asinh","atan","atanh","cbrt","ceil","cosh","cos","erf","erfc","exp","exp10","exp2","expm1","fabs","floor","j0","j1","lgamma","log","log10","log1p","log2","logb","nearbyint","rint","round","significand","sin","sinh","sqrt","tan","tanh","tgamma","trunc","y0","y1","gamma"]:
        _f = _libm_func(_nm, [_cdouble], _cdouble)
        if _f:
            _MATH1[_nm] = _f
    # binary: name -> (func, kind) kind: dd, di (int,double?) etc handled specially
    for _nm in ["atan2","copysign","drem","fdim","fmax","fmin","fmod","hypot","pow","remainder","scalb","nextafter"]:
        _f = _libm_func(_nm, [_cdouble, _cdouble], _cdouble)
        if _f:
            _MATH2[_nm] = _f
    _f = _libm_func("fma", [_cdouble, _cdouble, _cdouble], _cdouble)
    if _f:
        _MATH3["fma"] = _f

def _math1_py(name, x):
    try:
        if name == "fabs": return math.fabs(x)
        if name == "gamma": return math.lgamma(x)
        if name == "exp10": return 10.0 ** x
        if name == "significand":
            if x == 0: return 0.0
            m, e = math.frexp(x); return m * 2.0
        if name == "logb":
            if x == 0: return -math.inf
            m, e = math.frexp(abs(x)); return float(e - 1)
        if name == "j0" or name == "j1" or name == "y0" or name == "y1":
            return math.nan
        fn = getattr(math, name, None)
        if fn:
            return float(fn(x))
    except OverflowError:
        return math.inf
    except ValueError:
        # domain: distinguish -inf for log(0) etc
        if name in ("log", "log10", "log2", "log1p") and x == 0:
            return -math.inf
        return math.nan
    except Exception:
        return math.nan
    return math.nan

def call_math1(name, x):
    if name in _MATH1:
        return float(_MATH1[name](x))
    return _math1_py(name, x)

def call_math2(name, a, b):
    # a,b floats (for int-first functions, a is int value as float)
    if _libm is not None:
        try:
            if name in ("jn", "yn"):
                f = _libm_func(name, [_cint, _cdouble], _cdouble)
                if f: return float(f(int(a), b))
            if name == "ldexp":
                f = _libm_func("ldexp", [_cdouble, _cint], _cdouble)
                if f: return float(f(a, int(b)))
            if name == "scalbln":
                f = _libm_func("scalbln", [_cdouble, _clong], _cdouble)
                if f: return float(f(a, int(b)))
            if name == "nexttoward":
                f = getattr(_libm, "nexttoward")
                f.argtypes = [_cdouble, _ctypes_mod.c_longdouble]; f.restype = _cdouble
                return float(f(a, b))
            if name in _MATH2:
                return float(_MATH2[name](a, b))
        except Exception:
            pass
    # python fallbacks
    try:
        if name == "atan2": return math.atan2(a, b)
        if name == "copysign": return math.copysign(a, b)
        if name == "fmax": return a if a >= b else b
        if name == "fmin": return a if a <= b else b
        if name == "fmod" or name == "drem" or name == "remainder":
            if name == "fmod": return math.fmod(a, b)
            return math.remainder(a, b)
        if name == "hypot": return math.hypot(a, b)
        if name == "pow": return math.pow(a, b)
        if name == "ldexp": return math.ldexp(a, int(b))
        if name == "nextafter" or name == "nexttoward": return math.nextafter(a, b)
        if name == "scalb" or name == "scalbln": return a * (2.0 ** b)
        if name == "fdim": return a - b if a > b else 0.0
    except OverflowError:
        return math.inf
    except ValueError:
        return math.nan
    except Exception:
        return math.nan
    return math.nan

