def _contains(a, b):
    # does a contain b?
    if isinstance(a, str) and isinstance(b, str):
        return b in a
    if isinstance(a, list) and isinstance(b, list):
        return all(any(_contains(x, y) if False else jq_equal(x, y) or _contains_inner(x, y) for x in a) for y in b) if False else all(any(_contains(x, y) for x in a) for y in b)
    if isinstance(a, dict) and isinstance(b, dict):
        return all(k in a and _contains(a[k], v) for k, v in b.items())
    # scalars
    if type_name(a) == type_name(b) or (isinstance(a, JNum) and isinstance(b, JNum)):
        return jq_equal(a, b)
    err(f"{value_desc(a)} and {value_desc(b)} cannot have their containment checked")

def _contains_inner(a, b):
    return _contains(a, b)

