@reg("from_entries", 0)
def _b_from_entries(ctx, inp, env, args, node):
    if not isinstance(inp, list):
        # from_entries is map(...) so iterate error
        err(f"Cannot iterate over {value_desc(inp)}")
    obj = {}
    for entry in inp:
        # mimics jq def: {key: (.key // .Key // .name // .Name), value: (.value // .Value)} then object construction - errors if entry not indexable
        key = None
        found_key = False
        # .key access on entry (errors if number etc)
        k1 = index_value(entry, "key")
        if k1 is not None and k1 is not False:
            key = k1
        else:
            k2 = index_value(entry, "Key")
            if k2 is not None and k2 is not False:
                key = k2
            else:
                k3 = index_value(entry, "name")
                if k3 is not None and k3 is not False:
                    key = k3
                else:
                    k4 = index_value(entry, "Name")
                    key = k4
        v1 = index_value(entry, "value")
        if v1 is not None and v1 is not False:
            val = v1
        else:
            val = index_value(entry, "Value")
            # note: if .value is false, // falls through to .Value (jq semantics)
            if v1 is False:
                # Actually (.value // .Value): if .value==false, result .Value (could be null)
                pass
            elif v1 is None:
                pass
        # Recompute val exactly with // semantics:
        val = v1 if (v1 is not None and v1 is not False) else index_value(entry, "Value")
        if not isinstance(key, str):
            err(f"Cannot use {value_desc(key)} as object key")
        obj[key] = val
    yield obj

@reg("with_entries", 1)
def _b_with_entries(ctx, inp, env, args, node):
