def _sort_by_impl(ctx, inp, env, fnode):
    if not isinstance(inp, list):
        # sort_by defined via _sort_by: def sort_by(f): map([f, .]) | sort_by(.[0])... actually errors: Cannot iterate over ...
        err(f"Cannot iterate over {value_desc(inp)}")
    decorated = []
    for item in inp:
        keys = list(eval_node(fnode, item, env, ctx))
        decorated.append((keys, item))
    from functools import cmp_to_key
    def cmp(a, b):
        return jq_cmp(a[0], b[0])
    decorated.sort(key=cmp_to_key(cmp))
    return decorated

@reg("sort_by", 1)
def _b_sort_by(ctx, inp, env, args, node):
    yield [item for (_k, item) in _sort_by_impl(ctx, inp, env, args[0])]

@reg("group_by", 1)
def _b_group_by(ctx, inp, env, args, node):
    decorated = _sort_by_impl(ctx, inp, env, args[0])
    groups = []
    for keys, item in decorated:
        if groups and jq_equal(groups[-1][0], keys):
            groups[-1][1].append(item)
        else:
            groups.append((keys, [item]))
    yield [g for (_k, g) in groups]

@reg("unique", 0)
def _b_unique(ctx, inp, env, args, node):
    if not isinstance(inp, list):
        err(f"{value_desc(inp)} cannot be sorted, as it is not an array")
    from functools import cmp_to_key
    s = sorted(inp, key=cmp_to_key(jq_cmp))
    out = []
    for x in s:
        if not out or not jq_equal(out[-1], x):
            out.append(x)
    yield out

@reg("unique_by", 1)
def _b_unique_by(ctx, inp, env, args, node):
    decorated = _sort_by_impl(ctx, inp, env, args[0])
    out = []
    seen_keys = []
    for keys, item in decorated:
        if not any(jq_equal(keys, sk) for sk in seen_keys):
            seen_keys.append(keys)
            out.append(item)
    yield out

def _min_max_by(ctx, inp, env, fnode, want_max):
    # min/max on non-array error wording: "{desc} and {desc} cannot be iterated over" (from reduce definition)
    if not isinstance(inp, list):
        err(f"{value_desc(inp)} and {value_desc(inp)} cannot be iterated over")
    if len(inp) == 0:
        return None
    best = inp[0]
    best_keys = list(eval_node(fnode, best, env, ctx)) if fnode is not None else best
    for item in inp[1:]:
        keys = list(eval_node(fnode, item, env, ctx)) if fnode is not None else item
        c = jq_cmp(keys, best_keys)
        if (want_max and c > 0) or ((not want_max) and c < 0):
            best = item; best_keys = keys
    return best

