def _find_indices_str(s, sub):
    out = []
    if sub == "":
        return list(range(len(s)+1))
    i = 0
    while True:
        j = s.find(sub, i)
        if j < 0:
            break
        out.append(j); i = j + max(1, len(sub))
    return out

def _find_indices_arr(arr, sub):
    # sub can be a value (find elements equal) or list (find subarray)
    out = []
    if isinstance(sub, list):
        if len(sub) == 0:
            return list(range(len(arr)+1))
        for i in range(0, len(arr)-len(sub)+1):
            if all(jq_equal(arr[i+k], sub[k]) for k in range(len(sub))):
                out.append(i)
        return out
    for i, x in enumerate(arr):
        if jq_equal(x, sub):
            out.append(i)
    return out

