def _range_vals(start, end, step):
    for v in (start, end, step):
        _require_num(v)
    s = start.f; e = end.f; st = step.f
    if st == 0 or math.isnan(s) or math.isnan(e) or math.isnan(st):
        return
    x = s
    if st > 0:
        while x < e:
            yield N(x)
            x += st
            if math.isinf(x):
                break
    else:
        while x > e:
            yield N(x)
            x += st
            if math.isinf(x):
                break

