def _fromstream_events(events):
    # State machine rebuilding one top-level value at a time.
    # jq's fromstream is a state machine; approximate with a reconstruction algorithm:
    # We collect events until a top-level value is complete.
    # Simpler: collect all events, then reconstruct sequentially using setpath on leaves and truncation markers to know completion.
    # A top-level value is complete when:
    #  - a leaf event with path [] arrives (scalar/empty at root), or
    #  - a truncation event [ [k] ] (path length 1) arrives closing the root container, or events exhausted with a partially built root?
    # Algorithm with explicit stack:
    root = _FS_EMPTY
    root_started = False
    for ev in events:
        if not isinstance(ev, list) or len(ev) == 0:
            continue
        path = ev[0]
        if not isinstance(path, list):
            continue
        if len(ev) == 2:
            leaf = ev[1]
            if len(path) == 0:
                yield leaf
                root = _FS_EMPTY; root_started = False
                continue
            if not root_started:
                root = [] if isinstance(path[0], JNum) else {}
                root_started = True
            root = _fs_set(root, path, leaf)
        else:
            # truncation marker [path]: container at parent of path is complete
            if len(path) <= 1:
                if root_started:
                    yield root
                    root = _FS_EMPTY; root_started = False
                elif len(path) == 0:
                    pass
                continue
            # deeper truncation: nothing needed (structure already built by leaves, containers created on demand)
            continue
    # Note: incomplete root at end is not yielded (matches fromstream on truncations observed yielding nothing in some tests)

