    # setpath but creating containers based on next component; use setpath_value
    return setpath_value(root, path, leaf)

@reg("bsearch", 1)
def _b_bsearch(ctx, inp, env, args, node):
    for target in eval_node(args[0], inp, env, ctx):
        if not isinstance(inp, list):
            err(f"{value_desc(inp)} cannot be searched, as it is not an array" if False else f"Cannot iterate over {value_desc(inp)}")
        lo = 0; hi = len(inp)
        while lo < hi:
            mid = (lo + hi) // 2
            c = jq_cmp(inp[mid], target)
            if c < 0:
                lo = mid + 1
            elif c > 0:
                hi = mid
            else:
                yield N(mid); break
        else:
            yield N(-lo - 1)

