def _sub_with_engine(ctx, s, env, eng, repl_node):
    matches = list(regex_all_matches(eng, s)) if eng.is_global else []
    if not eng.is_global:
        m = eng.search_from(s.encode("utf-8"), 0)
        if m is not None:
            matches = [m]
    if not matches:
        yield s; return
    # Recursive generator over matches
    def rec(i, last_c, acc):
        if i == len(matches):
            yield acc + s[last_c:]; return
        m = matches[i]
        beg_c = _byte_to_char_idx(s, m.beg_b); end_c = _byte_to_char_idx(s, m.end_b)
        prefix = acc + s[last_c:beg_c]
        cap_obj = capture_object(eng, s, m)
        repl_vals = []
        # replacement output handling: evaluate; convert via "" + repl (arith_add) to reproduce type errors, but scalars: ""+number errors in jq
        got = False
        for rv in eval_node(repl_node, cap_obj, env, ctx):
            got = True
            # "" + rv using jq add: string+string ok, string+number error
            rstr = arith_add("", rv)
            yield from rec(i+1, end_c, prefix + rstr)
        if not got:
            # empty replacement leaves match unchanged (observed sub with empty returns subject)
            yield from rec(i+1, end_c, prefix + s[beg_c:end_c])
    yield from rec(0, 0, "")

