@reg("mktime", 0)
def _b_mktime(ctx, inp, env, args, node):
    if not isinstance(inp, list):
        err(f"{value_desc(inp)} mktime requires an array" if False else "mktime requires an array")
    def gi(i, d=0):
        if i < len(inp) and isinstance(inp[i], JNum):
            return inp[i].f
        return float(d)
    year = int(gi(0, 1970)); mon = int(gi(1, 0)); mday = int(gi(2, 1)); hour = int(gi(3)); minute = int(gi(4))
    sec_f = gi(5)
    sec_i = int(math.floor(sec_f)); frac = sec_f - sec_i
    # Use UTC (timegm) with normalization via datetime? Use calendar.timegm on a struct with possibly out-of-range fields normalized by time.mktime? jq uses its own mktime impl normalizing.
    # Use datetime with overflow handled by manual normalization via ordinal arithmetic:
    import calendar, datetime
    # Normalize month overflow
    total_months = year * 12 + mon
    ny = total_months // 12; nm = total_months % 12 + 1
    try:
        base = datetime.datetime(ny, nm, 1, tzinfo=datetime.timezone.utc) + datetime.timedelta(days=mday-1, hours=hour, minutes=minute, seconds=sec_i)
        ts = base.timestamp()
    except Exception:
        # fallback calendar.timegm (may overflow)
        try:
            ts = calendar.timegm((ny, nm, mday, hour, minute, sec_i, 0, 0, 0))
        except Exception:
            err("mktime: date out of range")
    yield N(ts + frac)

