def _sub_with_engine(ctx, s, env, eng, repl_node):
    matches = list(regex_all_matches(eng, s)) if eng.is_global else []
    if not eng.is_global:
        m = eng.search_from(s.encode("utf-8"), 0)
        if m is not None:
            matches = [m]
    if not matches:
        yield s; return
    # Recursive generator over matches
    def rec(i, last_c, acc):
        if i == len(matches):
            yield acc + s[last_c:]; return
        m = matches[i]
        beg_c = _byte_to_char_idx(s, m.beg_b); end_c = _byte_to_char_idx(s, m.end_b)
        prefix = acc + s[last_c:beg_c]
