# ---------------- Checker ----------------
class Checker:
    def __init__(self):
        self.errors = []
        self.checked = set()
        self.inprogress = set()
    def _err(self, msg, node):
        loc = node.loc
        if loc is None:
            self.errors.append(CompileError(msg))
            return
        caret = max(1, len(loc.source.text[loc.start:node.end].encode("utf-8", "surrogateescape")))
        self.errors.append(CompileError(msg, loc.source, loc.line, loc.col, caret))
    def check(self, node, env):
        if node is None:
            return
        k = node.kind
        if k in ("lit", "identity", "loc", "format"):
            return
        if k == "str":
            for p in node.x[0]:
                if not isinstance(p, str):
                    self.check(p, env)
            return
        if k == "var":
            found, _v = env.lookup_var(node.x[0])
            if not found:
                self._err(f"${node.x[0]} is not defined", node)
            return
        if k == "call":
            name, args = node.x
            uf = env.lookup_func(name, len(args))
            if uf is None and (name, len(args)) not in BUILTINS:
                self._err(f"{name}/{len(args)} is not defined", node)
                return
            if uf is not None and uf.kind == "user":
                self._check_user(uf)
            for a in args:
                self.check(a, env)
            return
        if k == "def":
            name, params, body, rest = node.x
            env2, _uf = make_def_env(env, name, params, body)
            self.check(rest, env2)
            return
        if k == "funcdef":
            return
        if k == "bind":
            source, patterns, body = node.x
            self.check(source, env)
            for pat in patterns:
                self._check_pattern_keys(pat, env)
            allvars = set()
            for pat in patterns:
                allvars |= pattern_vars(pat)
            env2 = env.child(vars={v: None for v in allvars})
            self.check(body, env2)
            return
        if k in ("reduce", "foreach"):
            if k == "reduce":
                source, patterns, init, update = node.x; extract = None
            else:
                source, patterns, init, update, extract = node.x
            self.check(source, env)
            for pat in patterns:
                self._check_pattern_keys(pat, env)
            self.check(init, env)
            allvars = set()
            for pat in patterns:
                allvars |= pattern_vars(pat)
            env2 = env.child(vars={v: None for v in allvars})
            self.check(update, env2)
            if extract is not None:
                self.check(extract, env2)
            return
        if k == "label":
            name, body = node.x
            env2 = env.child(vars={f"*label-{name}": None})
            self.check(body, env2)
            return
        if k == "break":
            found, _v = env.lookup_var(f"*label-{node.x[0]}")
            if not found:
                self._err(f"$*label-{node.x[0]} is not defined", node)
            return
        if k == "object":
            for (kk, kd, val, _kloc) in node.x[0]:
                if kk == "str":
                    self.check(kd, env)
                elif kk == "expr":
                    self.check(kd, env)
                    # constant key check
                    try:
                        cv = eval_constant_node(kd)
                        if not isinstance(cv, str):
                            self._err(f"Cannot use {value_desc(cv)} as object key", kd)
                    except NotConstant:
                        pass
                if val is not None:
                    self.check(val, env)
            return
        # Generic traversal for remaining kinds in a sensible order
        if k == "postfix":
            base, suffixes = node.x
            self.check(base, env)
            for sfx in suffixes:
                if sfx[0] == "index":
                    self.check(sfx[1], env)
                elif sfx[0] == "slice":
                    if sfx[1] is not None: self.check(sfx[1], env)
                    if sfx[2] is not None: self.check(sfx[2], env)
            return
        if k == "if":
            branches, else_node = node.x
            for cond, branch in branches:
                self.check(cond, env); self.check(branch, env)
            if else_node is not None:
                self.check(else_node, env)
            return
        if k == "try":
            body, catch = node.x
            self.check(body, env)
            if catch is not None:
