# ---------------- Modules ----------------
class LoadedModule:
    __slots__ = ("prog", "exports", "path", "meta")
    def __init__(self, prog, exports, path, meta):
        self.prog = prog; self.exports = exports; self.path = path; self.meta = meta

def _expand_search_entry(entry, ctx):
    if entry.startswith("~/"):
        home = os.environ.get("HOME") or os.path.expanduser("~")
        entry = home + entry[1:]
    if entry.startswith("$ORIGIN"):
        entry = ctx.jq_origin + entry[len("$ORIGIN"):]
    return entry

def _resolve_module(ctx, relpath, is_data, meta, importer_dir):
    ext = ".json" if is_data else ".jq"
    dirs = []
    if meta is not None and isinstance(meta, dict) and "search" in meta:
        search = meta.get("search")
        if isinstance(search, str):
            raw = [search]
        elif isinstance(search, list):
            raw = [x for x in search if isinstance(x, str)]
        else:
            raw = []
        for d in raw:
            d = _expand_search_entry(d, ctx)
            if not os.path.isabs(d):
                d = os.path.join(importer_dir, d)
            dirs.append(d)
    else:
        dirs = ["."] + [_expand_search_entry(e, ctx) for e in ctx.search_list]
    for d in dirs:
        cand = d + relpath + ext if d.endswith("/") else d + "/" + relpath + ext
        if os.path.lexists(cand):
            return os.path.realpath(cand)
    return None

def _module_not_found(relpath):
    raise JqCompileException([CompileError(None, raw=f"jq: error: module not found: {relpath}\n\n")])

def _module_meta_for(prog):
    meta = dict(prog.meta) if isinstance(prog.meta, dict) else {}
    deps = []
    for imp in prog.imports:
        d = dict(imp["meta"]) if isinstance(imp.get("meta"), dict) else {}
        if imp.get("alias"):
            d["as"] = imp["alias"]
        d["is_data"] = bool(imp.get("is_data"))
        d["relpath"] = imp["path"]
        deps.append(d)
    meta["deps"] = deps
    meta["defs"] = [f"{d.x[0]}/{len(d.x[1])}" for d in prog.defs]
    return meta

def _read_file_bytes(path):
    with open(path, "rb") as f:
        return f.read()

def _load_import(ctx, imp, importer_dir, global_env):
    relpath = imp["path"]
    is_data = imp.get("is_data")
    resolved = _resolve_module(ctx, relpath, is_data, imp.get("meta"), importer_dir)
    if resolved is None:
        _module_not_found(relpath)
    if is_data:
        try:
            data = _read_file_bytes(resolved)
        except OSError as e:
            msg = "It's a directory" if e.errno == 21 else (e.strerror or str(e))
            raise JqCompileException([CompileError(None, raw=f"jq: error loading data file {resolved}: Could not open {resolved}: {msg}\n\n")])
        p = JsonParser()
        p.feed(data); p.finish()
        if p.pending_error is not None:
            raise JqCompileException([CompileError(None, raw=f"jq: error loading data file {resolved}: {p.pending_error.display}\n\n")])
        values = [v for (v, _e, _l) in p.queue]
        return ("data", values)
    # code module
    if resolved in ctx.module_cache:
        loaded = ctx.module_cache[resolved]
        ctx.modules[relpath] = loaded.meta
        return ("code", loaded)
    if resolved in ctx.loading_stack:
        raise JqCompileException([CompileError(None, raw=f"jq: error: module not found: {relpath}\n\n")])
    try:
        data = _read_file_bytes(resolved)
    except OSError as e:
        msg = "It's a directory" if e.errno == 21 else (e.strerror or str(e))
        raise JqCompileException([CompileError(None, raw=f"jq: error: Could not open {resolved}: {msg}\n\n")])
    text = data.decode("utf-8", "surrogateescape")
    source = Source(resolved, text)
    parser = Parser(source)
    prog = parser.parse_program(is_library=True)
    meta = _module_meta_for(prog)
    ctx.modules[relpath] = meta
    ctx.loading_stack.append(resolved)
    try:
        internal_base = Env(parent=global_env)
        internal_env = _apply_imports(ctx, prog.imports, internal_base, os.path.dirname(resolved), global_env)
        exports = {}
        env_cur = internal_env
        for fdef in prog.defs:
            name, params, body = fdef.x
            env_cur, uf = make_def_env(env_cur, name, params, body)
            exports[(name, len(params))] = uf
    finally:
        ctx.loading_stack.pop()
    loaded = LoadedModule(prog, exports, resolved, meta)
    ctx.module_cache[resolved] = loaded
    return ("code", loaded)

def _apply_imports(ctx, imports, base_env, importer_dir, global_env):
    loaded = {}
    for imp in reversed(imports):
        loaded[id(imp)] = _load_import(ctx, imp, importer_dir, global_env)
