            try:
                out_buf.flush()
            except Exception:
                pass
            return ("halt", h.code)
        except JqError as e:
            error_display(ctx, provider, e)
            return ("error", 5)
        except BreakLabel as b:
            # Unmatched break would be compile error; treat as error
            error_display(ctx, provider, JqError(f"break ${b.name}"))
