        except RecursionError:
            _write_stderr_bytes(b"jq: error: cannot allocate memory\n")
            return ("halt", 5)
        if opts.exit_status:
            if not has_out:
                return ("ok", 4)
            if last_out is False or last_out is None:
                return ("ok", 1)
            return ("ok", 0)
        return ("ok", 0)

    ret = 0
    try:
        if opts.null_input:
            kind, code = process_one(None)
            ret = code
            if provider.had_file_error:
                ret = 2
        elif opts.slurp:
            if opts.raw_input:
                sval = provider.read_all_raw()
                kind, code = process_one(sval)
                ret = code
            else:
                vals = []
                try:
                    while True:
                        vals.append(provider.next_for_main())
                except StopIteration:
                    pass
                kind, code = process_one(vals)
                ret = code
            if provider.had_file_error:
                ret = 2
        else:
            saw_any = False
            while True:
                try:
                    v = provider.next_for_main()
                except StopIteration:
                    break
                saw_any = True
                kind, code = process_one(v)
                ret = code
                if provider.had_file_error:
                    ret = 2
                    break
                if kind == "halt":
                    break
            if provider.had_file_error:
                ret = 2
            elif not saw_any and opts.exit_status:
