        _write_stderr_bytes(f"jq: parse error: {e.perr.display}\n".encode("utf-8", "replace"))
        ret = 5
        if provider.had_file_error:
            ret = 2
    try:
        out_buf.flush()
    except Exception:
        pass
    return ret

