def _parse_named_json(text, optname):
    try:
        return parse_single_json_text(text)
    except Exception:
        _cli_error_exit(f"jq: invalid JSON text passed to {optname}\n")

def _load_slurpfile(name, fname, optname="--slurpfile"):
    try:
        data = load_file_bytes_for_cli(fname)
    except OSError as e:
        _write_stderr_bytes(f"jq: Bad JSON in {optname} {name} {fname}: Could not open {fname}: {cli_file_error_str(e)}\n".encode("utf-8", "replace"))
        raise SystemExit(2)
    p = JsonParser()
    p.feed(data); p.finish()
    if p.pending_error is not None:
        _write_stderr_bytes(f"jq: Bad JSON in {optname} {name} {fname}: {p.pending_error.display}\n".encode("utf-8", "replace"))
        raise SystemExit(2)
    return [v for (v, _e, _l) in p.queue]

def _load_rawfile(name, fname):
    try:
