    "--unbuffered": "unbuf", "--stream": "stream", "--stream-errors": "streamerr", "--seq": "seq",
    "--from-file": "fromfile", "--exit-status": "exitst",
}

def _apply_noarg(opts, key):
    if key == "null": opts.null_input = True
    elif key == "raw": opts.raw_input = True
    elif key == "slurp": opts.slurp = True
    elif key == "compact": opts.compact = True
    elif key == "rawout": opts.raw_output = True
    elif key == "raw0": opts.raw_output0 = True; opts.raw_output = True
    elif key == "join": opts.join_output = True; opts.raw_output = True
    elif key == "ascii": opts.ascii = True
    elif key == "sort": opts.sort_keys = True
    elif key == "color": opts.color = True
    elif key == "mono": opts.mono = True
    elif key == "tab": opts.indent = -1
    elif key == "unbuf": opts.unbuffered = True
    elif key == "stream": opts.stream = True
    elif key == "streamerr": opts.stream = True; opts.stream_errors = True
    elif key == "seq": opts.seq = True
    elif key == "fromfile": opts.from_file = True
    elif key == "exitst": opts.exit_status = True

def parse_cli(argv):
    opts = Options()
    options_enabled = True
    args_mode = None  # None|str|json
    i = 0
    n = len(argv)
    while i < n:
        arg = argv[i]
        is_opt = False
        if options_enabled and len(arg) > 1 and arg[0] == "-" and (arg[1] == "-" or ("A" <= arg[1] <= "Z") or ("a" <= arg[1] <= "z")):
            is_opt = True
        if options_enabled and arg == "--":
            options_enabled = False
            i += 1
            continue
        if is_opt:
            if arg.startswith("--"):
                # long option exact
                if arg == "--help":
                    sys.stdout.write(HELP_TEXT); raise SystemExit(0)
                if arg == "--version":
                    sys.stdout.write(VERSION + "\n"); raise SystemExit(0)
                if arg == "--build-configuration":
                    sys.stdout.write(BUILD_CONFIG + "\n"); raise SystemExit(0)
                if arg in _LONG_OPTS_NOARG:
                    _apply_noarg(opts, _LONG_OPTS_NOARG[arg])
                    i += 1; continue
                if arg == "--args":
                    args_mode = "str"; i += 1; continue
                if arg == "--jsonargs":
                    args_mode = "json"; i += 1; continue
                if arg == "--indent":
                    if i + 1 >= n:
                        _cli_error_exit("jq: --indent takes one parameter\n")
                    v = argv[i+1]; i += 2
                    if not re.fullmatch(r"[+-]?[0-9]+", v) or not (-1 <= int(v) <= 7):
                        _cli_error_exit("jq: --indent takes a number between -1 and 7\n")
                    opts.indent = int(v); continue
                if arg == "--library-path":
                    if i + 1 >= n:
                        _cli_error_exit("-L takes a parameter: (e.g. -L /search/path or -L/search/path)\n")
                    opts.library_paths.append(argv[i+1]); i += 2; continue
                if arg in ("--arg", "--argjson", "--slurpfile", "--rawfile"):
                    spec = {"--arg": "varname value", "--argjson": "varname text", "--slurpfile": "varname filename", "--rawfile": "varname filename"}[arg]
                    if i + 2 >= n:
                        _cli_error_exit(f"jq: {arg} takes two parameters (e.g. {arg} {spec})\n")
                    nm = argv[i+1]; val = argv[i+2]; i += 3
                    if arg == "--arg":
                        opts.named.append((nm, val))
                    elif arg == "--argjson":
                        opts.named.append((nm, _parse_named_json(val, "--argjson")))
                    elif arg == "--slurpfile":
                        opts.named.append((nm, _load_slurpfile(nm, val, "--slurpfile")))
                    else:
                        opts.named.append((nm, _load_rawfile(nm, val)))
                    continue
                _cli_error_exit(f"jq: Unknown option {arg}\n")
            else:
                # short bundle
                j = 1
                consumed_next = False
                while j < len(arg):
                    ch = arg[j]
                    if ch == "h":
                        sys.stdout.write(HELP_TEXT); raise SystemExit(0)
                    if ch == "V":
                        sys.stdout.write(VERSION + "\n"); raise SystemExit(0)
                    if ch == "n": opts.null_input = True
                    elif ch == "R": opts.raw_input = True
                    elif ch == "s": opts.slurp = True
                    elif ch == "c": opts.compact = True
                    elif ch == "r": opts.raw_output = True
                    elif ch == "j": opts.join_output = True; opts.raw_output = True
                    elif ch == "a": opts.ascii = True
                    elif ch == "S": opts.sort_keys = True
                    elif ch == "C": opts.color = True
                    elif ch == "M": opts.mono = True
                    elif ch == "e": opts.exit_status = True
                    elif ch == "f": opts.from_file = True
                    elif ch == "L":
                        rest = arg[j+1:]
                        if rest:
                            opts.library_paths.append(rest)
                            j = len(arg)
                            break
                        else:
                            if i + 1 >= n:
                                _cli_error_exit("-L takes a parameter: (e.g. -L /search/path or -L/search/path)\n")
                            opts.library_paths.append(argv[i+1])
                            consumed_next = True
                            j += 1
                            break
                    else:
                        _cli_error_exit(f"jq: Unknown option -{ch}\n")
                    j += 1
                i += 2 if consumed_next else 1
                continue
        # non-option
        if opts.filter_arg is None:
            opts.filter_arg = arg
        elif args_mode is not None:
            if args_mode == "str":
                opts.positional.append(arg)
            else:
                opts.positional.append(_parse_named_json(arg, "--jsonargs"))
        else:
            opts.files.append(arg)
        i += 1
    return opts

